#!/usr/bin/env bash
#
# verify.sh — the day-to-day "secure by assertion" CI gate (§9.2/§9.3, R-V3).
#
# Runs against one already-present immutable devcheck image on the pinned 1.75
# toolchain. This verdict path never builds, pulls, tags, or resolves an image:
#   1. the §10.4 PAKE KATs + the R-P3 self-consistency / negative KATs (R-A10);
#   2. the wire-level CPace handshake + two-key-cipher integration tests;
#   3. the R-S16 PINNED_SETTINGS policy funnel test (now unconditional, R-R2b);
#   4. a compile check of the whole main crate (hardening unconditional);
#   5. the R-A6 build-time greps — forbidden tokens of the completed excisions
#      and closed follow-up stages MUST be absent.
#
# This is the reproducible assurance basis the §11 review and the spec's
# "secure by assertion" gates rest on. It is NOT the release build (that is the
# vcpkg flow in build-debian.sh). Exit non-zero if any gate fails.
#
# COMPANION GATE: scripts/audit.sh runs the R-R3/R-A7 dependency-advisory check
# for the Rust crate graph (cargo-audit + cargo-deny against deny.toml and a pinned advisory-db),
# and scripts/dart-audit.sh is its Dart-side mirror (osv-scanner against
# flutter/pubspec.lock + the deny-style accept-list scripts/dart-audit-ignores.txt,
# offline against a pinned OSV "Pub" snapshot). Both are kept separate because they
# need an advisory-db + a tool fetch/compile — slower, and run in CI / before a
# release rather than on every inner-loop edit.
#
# COMPANION GATE: scripts/native-codec-watch.sh is the offline source gate for
# vcpkg-built native codec/advisory coverage. Cargo/Dart advisory tools do not
# see those C/C++ libraries, so this gate keeps the manual watch ledger in sync
# with the exact vcpkg manifest and pins; it is not the decoder sandbox.
#
# COMPANION GATE: scripts/apple-conform-check.sh runs the R-R2 Apple (macOS/iOS)
# SOURCE-conformance gate: retain-and-check, R-A6 greps on the Apple cfg, structured
# plist/entitlement/pod/Xcode allow-lists, and cargo cross-checks across the documented
# Apple target matrix with the real Apple Flutter features. Kept separate because it
# builds a second toolchain image and cross-checks the Apple targets (slower), and Apple
# is NOT a build target (R-R2). The Linux `cargo check` below cannot see the cfg(macos)/
# cfg(ios) clusters, so that gate is where their hardening is proven.
#
# Usage:  scripts/verify.sh
set -euo pipefail

VERIFY_WORKSPACE_SELF_TEST=0
VERIFY_WORKSPACE_MISSING_SELF_TEST=0
for argument in "$@"; do
  case "$argument" in
    --self-test-workspace) VERIFY_WORKSPACE_SELF_TEST=1 ;;
    --self-test-workspace-missing) VERIFY_WORKSPACE_MISSING_SELF_TEST=1 ;;
    *) echo "verify: unknown argument: $argument" >&2; exit 1 ;;
  esac
done
[ "$((VERIFY_WORKSPACE_SELF_TEST + VERIFY_WORKSPACE_MISSING_SELF_TEST))" -le 1 ] \
  || { echo "verify: workspace self-test modes are mutually exclusive" >&2; exit 1; }

cd "$(dirname "$0")/.."

# shellcheck source=scripts/lib.sh
source scripts/lib.sh
load_pins

# shellcheck source=scripts/verify-scan.sh
source scripts/verify-scan.sh
verify_scan_preflight

VERIFY_TMP=""
VERIFY_TMP_ID=""
VERIFY_SUCCESS_MESSAGE=""
cleanup_verify_tmp() {
  local status=$? cleanup_failed=0
  trap - EXIT
  trap '' HUP INT TERM
  if [ -n "$VERIFY_TMP" ]; then
    if [ -z "$VERIFY_TMP_ID" ] || [ ! -d "$VERIFY_TMP" ] || [ -L "$VERIFY_TMP" ] \
      || [ "$(stat -c '%d:%i' -- "$VERIFY_TMP" 2>/dev/null)" != "$VERIFY_TMP_ID" ]; then
      echo "verify: private workspace identity is unavailable or changed: $VERIFY_TMP" >&2
      cleanup_failed=1
    elif ! /usr/bin/python3 scripts/verify-private-tree-closure.py \
      --remove-private-root "$VERIFY_TMP" --expected-identity "$VERIFY_TMP_ID"; then
      echo "verify: failed to remove private workspace: $VERIFY_TMP" >&2
      cleanup_failed=1
    elif [ -e "$VERIFY_TMP" ] || [ -L "$VERIFY_TMP" ]; then
      echo "verify: private workspace remains after removal: $VERIFY_TMP" >&2
      cleanup_failed=1
    fi
  fi
  [ "$cleanup_failed" -eq 0 ] || [ "$status" -ne 0 ] || status=1
  if [ "$cleanup_failed" -eq 0 ] && [ "$status" -eq 0 ] && [ -n "$VERIFY_SUCCESS_MESSAGE" ]; then
    echo "$VERIFY_SUCCESS_MESSAGE"
  fi
  exit "$status"
}
trap cleanup_verify_tmp EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
VERIFY_TMP=$(umask 077 && mktemp -d /tmp/rustdesk-verify.XXXXXXXXXX)
VERIFY_TMP_ID="$(stat -c '%d:%i' -- "$VERIFY_TMP")"
readonly VERIFY_TMP VERIFY_TMP_ID
if ! python3 - "$VERIFY_TMP" <<'PY'
import os
import stat
import sys

metadata = os.lstat(sys.argv[1])
if (
    not stat.S_ISDIR(metadata.st_mode)
    or metadata.st_uid != os.geteuid()
    or stat.S_IMODE(metadata.st_mode) != 0o700
):
    raise SystemExit("verify: private workspace is not a current-UID mode-0700 directory")
PY
then
  exit 1
fi
if [ "$VERIFY_WORKSPACE_SELF_TEST" -eq 1 ]; then
  VERIFY_SUCCESS_MESSAGE="verify workspace self-test: OK"
  exit 0
fi
if [ "$VERIFY_WORKSPACE_MISSING_SELF_TEST" -eq 1 ]; then
  VERIFY_SUCCESS_MESSAGE="verify workspace missing self-test: INVALID SUCCESS"
  rm -rf -- "$VERIFY_TMP"
  echo "verify workspace missing self-test: REACHED" >&2
  exit 0
fi
verify_scan_self_test "$VERIFY_TMP"
readonly VERIFIER_FIXTURE_TMP="$VERIFY_TMP/verifier-fixtures"
install -d -m 0700 "$VERIFIER_FIXTURE_TMP"

# The fork-version reader/validator (defines fork_version; see docs/VERSIONING.md).
# shellcheck source=scripts/fork-version.sh
source scripts/fork-version.sh
readonly DOCKER_BIN=/usr/bin/docker
rc=0

echo "== (0) verifier workspace authority + release source/workflow ordering (R-S11c-10w/R-B2) =="
r_s11c10w=
if ! /usr/bin/python3 -I -S scripts/verify-verifier-workspace.py --repo . --self-test --scratch "$VERIFIER_FIXTURE_TMP"; then
  r_s11c10w="$r_s11c10w workspace-or-release-source-mutation-gate-failed"
fi
grep -qF 'R-S11c-10w — verifier private scratch workspace authority' HARDENING_STATUS.md || r_s11c10w="$r_s11c10w hardening-ledger-missing"
grep -qF 'Verifier private scratch workspace authority' requirements.html || r_s11c10w="$r_s11c10w requirements-disposition-missing"
if [ -n "$r_s11c10w" ]; then echo "  FAIL R-S11c-10w/R-B2 verifier workspace or release source ordering:$r_s11c10w"; rc=1; else
  echo "  ok  R-S11c-10w/R-B2 private verifier workspace + same-clean-HEAD release verification + publish/version workflow ordering"; fi

echo "== (0a) dependency, workflow, build-script, and unsafe-source inventory =="
inventory_gate=
if ! python3 scripts/dependency-inventory.py --self-test; then
  inventory_gate="$inventory_gate verifier-self-test-failed"
fi
inventory_status=0
python3 scripts/dependency-inventory.py --text || inventory_status=$?
case "$inventory_status" in
  0) ;;
  1) inventory_gate="$inventory_gate repository-inventory-drift" ;;
  2) inventory_gate="$inventory_gate repository-inventory-error" ;;
  *) inventory_gate="$inventory_gate repository-inventory-verifier-failed-$inventory_status" ;;
esac
if [ -n "$inventory_gate" ]; then
  echo "  FAIL repository inventory:$inventory_gate"
  rc=1
else
  echo "  ok  machine-derived dependency and executable build-surface inventory"
fi

echo "== (0b) R-V3 audit handoff scope and honest-status drift gate =="
r_v3_scope=
git ls-files --error-unmatch docs/CRYPTO-AUDIT-SCOPE.md \
  scripts/verify-crypto-audit-scope.py >/dev/null 2>&1 \
  || r_v3_scope="$r_v3_scope untracked-handoff-or-verifier"
if ! /usr/bin/python3 -I -S scripts/verify-crypto-audit-scope.py --self-test; then
  r_v3_scope="$r_v3_scope scope-or-mutation-self-test-failed"
fi
if [ -n "$r_v3_scope" ]; then
  echo "  FAIL R-V3 external-audit handoff drift:$r_v3_scope"
  rc=1
else
  echo "  ok  R-V3 exact-commit external-audit handoff names current mandatory roots/symbols, rejects stale line citations and self-signoff, and remains explicitly outstanding"
fi

echo "== (0c) main verifier immutable-container authority (R-S11bg) =="
r_s11bg=
if ! /usr/bin/python3 -I -S scripts/prepare-root-ipc-test.py --self-test; then
  r_s11bg="$r_s11bg root-artifact-helper-self-test-failed"
fi
if ! /usr/bin/python3 -I -S scripts/verify-main-verifier-authority.py --repo . --self-test; then
  r_s11bg="$r_s11bg authority-mutation-gate-failed"
fi
if [ -n "$r_s11bg" ]; then
  echo "  FAIL R-S11bg main verifier authority:$r_s11bg"
  rc=1
else
  echo "  ok  R-S11bg exact local image + private source/vendor/output state + non-root ordinary execution + isolated minimal-capability root tests"
fi

[ "$rc" -eq 0 ] || {
  echo "VERIFY: FAILED before container execution"
  exit 1
}

echo "== preparing the confined compile/test transaction (R-S11bg) =="
[ "$(id -u)" -ne 0 ] || { echo "verify: refuses host or container-root execution" >&2; exit 1; }
[ "$(id -g)" -ne 0 ] || { echo "verify: refuses a root primary group" >&2; exit 1; }
[ -x "$DOCKER_BIN" ] || { echo "verify: trusted Docker client is unavailable: $DOCKER_BIN" >&2; exit 1; }
: "${DEV_CHECK_IMAGE_ID:?verify: DEV_CHECK_IMAGE_ID is unset}"
: "${SHA256_DEV_CHECK_DOCKERFILE:?verify: SHA256_DEV_CHECK_DOCKERFILE is unset}"
: "${SHA256_DEV_CHECK_CARGO:?verify: SHA256_DEV_CHECK_CARGO is unset}"
: "${SHA256_DEV_CHECK_RUSTC:?verify: SHA256_DEV_CHECK_RUSTC is unset}"
: "${SHA256_DEV_CHECK_DPKG_MANIFEST:?verify: SHA256_DEV_CHECK_DPKG_MANIFEST is unset}"
: "${SHA256_CARGO_VENDOR_CLOSURE_V1:?verify: SHA256_CARGO_VENDOR_CLOSURE_V1 is unset}"
: "${SHA256_CARGO_VENDOR_CONFIG:?verify: SHA256_CARGO_VENDOR_CONFIG is unset}"
[[ "$DEV_CHECK_IMAGE_ID" =~ ^sha256:[0-9a-f]{64}$ ]] \
  || { echo "verify: malformed immutable devcheck image ID" >&2; exit 1; }
[ "$(sha256sum scripts/Dockerfile.devcheck | awk '{print $1}')" = "$SHA256_DEV_CHECK_DOCKERFILE" ] \
  || { echo "verify: devcheck acquisition recipe differs from its reviewed pin" >&2; exit 1; }
[ "$(sha256sum online/cargo-vendor-config.toml | awk '{print $1}')" = "$SHA256_CARGO_VENDOR_CONFIG" ] \
  || { echo "verify: Cargo vendor source map differs from its pin" >&2; exit 1; }

IMAGE_ID="$($DOCKER_BIN image inspect --format '{{.Id}}' "$DEV_CHECK_IMAGE_ID")" \
  || { echo "verify: immutable devcheck image is not present locally" >&2; exit 1; }
[ "$IMAGE_ID" = "$DEV_CHECK_IMAGE_ID" ] \
  || { echo "verify: local devcheck image identity differs from its pin" >&2; exit 1; }
readonly IMAGE_ID

archive_current_source() {
  git -C "$PWD" ls-files -z --cached --others --exclude-standard \
    | /usr/bin/python3 -c '
import os
import sys

root = os.fsencode(sys.argv[1])
for relative in sys.stdin.buffer.read().split(b"\0"):
    if relative and os.path.lexists(os.path.join(root, relative)):
        sys.stdout.buffer.write(relative + b"\0")
' "$PWD" \
    | tar --create --file=- --directory="$PWD" --null --verbatim-files-from \
        --no-recursion --files-from=- --sort=name --format=gnu --mtime='@0' \
        --owner=0 --group=0 --numeric-owner
}

readonly VERIFY_SOURCE_ARCHIVE="$VERIFY_TMP/source.tar"
readonly VERIFY_SOURCE="$VERIFY_TMP/source"
readonly VERIFY_VENDOR_PARENT="$VERIFY_TMP/vendor-input"
readonly VERIFY_VENDOR="$VERIFY_VENDOR_PARENT/subtree"
readonly VERIFY_TARGET="$VERIFY_TMP/target"
readonly VERIFY_CARGO_CONFIG="$VERIFY_TMP/cargo-config.toml"
install -d -m 0700 "$VERIFY_SOURCE" "$VERIFY_TARGET"
archive_current_source >"$VERIFY_SOURCE_ARCHIVE"
SOURCE_DIGEST="$(sha256sum "$VERIFY_SOURCE_ARCHIVE" | awk '{print $1}')"
readonly SOURCE_DIGEST
tar --extract --file="$VERIFY_SOURCE_ARCHIVE" --directory="$VERIFY_SOURCE" --no-same-owner
chmod -R a-w "$VERIFY_SOURCE"
/usr/bin/python3 scripts/online-input-provenance.py snapshot-subtree-create \
  --source online/cargo-vendor \
  --destination "$VERIFY_VENDOR_PARENT" \
  --expected "$SHA256_CARGO_VENDOR_CLOSURE_V1"
{
  printf '[net]\noffline = true\n'
  sed 's#directory = .*#directory = "/vendor"#' online/cargo-vendor-config.toml
} >"$VERIFY_CARGO_CONFIG"
chmod 0400 "$VERIFY_CARGO_CONFIG"
[ "$(grep -c '^directory = "/vendor"$' "$VERIFY_CARGO_CONFIG")" -eq 1 ] \
  || { echo "verify: private Cargo source map has an invalid vendor-directory cardinality" >&2; exit 1; }
[ "$(stat -c '%u:%g:%a:%h' "$VERIFY_TARGET")" = "$(id -u):$(id -g):700:2" ] \
  || { echo "verify: private Cargo target has invalid metadata" >&2; exit 1; }
[ "$(stat -c '%u:%g:%a:%h' "$VERIFY_CARGO_CONFIG")" = "$(id -u):$(id -g):400:1" ] \
  || { echo "verify: private Cargo config has invalid metadata" >&2; exit 1; }

readonly IMAGE_PREFLIGHT_OUT="$VERIFY_TMP/image-preflight.out"
readonly IMAGE_PREFLIGHT_ERR="$VERIFY_TMP/image-preflight.err"
set +e
"$DOCKER_BIN" run --rm --pull=never --network=none --read-only \
  --user "$(id -u):$(id -g)" \
  --cap-drop=ALL --security-opt=no-new-privileges \
  --pids-limit=32 --memory=256m --memory-swap=256m --cpus=1 \
  --tmpfs /tmp:rw,noexec,nosuid,nodev,mode=1777,size=16m \
  --env RUSTUP_TOOLCHAIN=1.75.0 \
  "$IMAGE_ID" /bin/bash -euo pipefail -c '
    [ "$(id -u)" -ne 0 ] && [ "$(id -g)" -ne 0 ]
    printf "rustc=%s\n" "$(rustc --version)"
    printf "cargo=%s\n" "$(cargo --version)"
    cargo_sha="$(sha256sum /usr/local/cargo/bin/cargo)"; cargo_sha="${cargo_sha%% *}"
    rustc_sha="$(sha256sum /usr/local/rustup/toolchains/1.75.0-x86_64-unknown-linux-gnu/bin/rustc)"; rustc_sha="${rustc_sha%% *}"
    dpkg_sha="$(dpkg-query -W | LC_ALL=C sort | sha256sum)"; dpkg_sha="${dpkg_sha%% *}"
    printf "cargo-sha=%s\n" "$cargo_sha"
    printf "rustc-sha=%s\n" "$rustc_sha"
    printf "dpkg-sha=%s\n" "$dpkg_sha"
    printf "sodium=%s\n" "${SODIUM_USE_PKG_CONFIG-}"
  ' >"$IMAGE_PREFLIGHT_OUT" 2>"$IMAGE_PREFLIGHT_ERR"
IMAGE_PREFLIGHT_STATUS=$?
set -e
[ "$IMAGE_PREFLIGHT_STATUS" -eq 0 ] && [ ! -s "$IMAGE_PREFLIGHT_ERR" ] \
  || { echo "verify: immutable devcheck image preflight failed" >&2; cat "$IMAGE_PREFLIGHT_ERR" >&2; exit 1; }
EXPECTED_IMAGE_PREFLIGHT="$VERIFY_TMP/image-preflight.expected"
cat >"$EXPECTED_IMAGE_PREFLIGHT" <<EOF
rustc=rustc 1.75.0 (82e1608df 2023-12-21)
cargo=cargo 1.75.0 (1d8b05cdd 2023-11-20)
cargo-sha=$SHA256_DEV_CHECK_CARGO
rustc-sha=$SHA256_DEV_CHECK_RUSTC
dpkg-sha=$SHA256_DEV_CHECK_DPKG_MANIFEST
sodium=1
EOF
chmod 0600 "$EXPECTED_IMAGE_PREFLIGHT"
cmp "$EXPECTED_IMAGE_PREFLIGHT" "$IMAGE_PREFLIGHT_OUT" \
  || { echo "verify: immutable devcheck image contents differ from reviewed pins" >&2; exit 1; }

RUN=("$DOCKER_BIN" run --rm --pull=never --network=none --read-only
  --user "$(id -u):$(id -g)"
  --cap-drop=ALL --security-opt=no-new-privileges
  --pids-limit=512 --memory=12g --memory-swap=12g --cpus=4
  --tmpfs /tmp:rw,exec,nosuid,nodev,mode=1777,size=2g
  --mount "type=bind,source=$VERIFY_SOURCE,target=/work,readonly"
  --mount "type=bind,source=$VERIFY_VENDOR,target=/vendor,readonly"
  --mount "type=bind,source=$VERIFY_TARGET,target=/build"
  --mount "type=bind,source=$VERIFY_CARGO_CONFIG,target=/tmp/cargo-config.toml,readonly"
  --env HOME=/tmp/verify-home
  --env CARGO_HOME=/tmp/cargo-home
  --env CARGO_TARGET_DIR=/build
  --env CARGO_INCREMENTAL=0
  --env CARGO_NET_OFFLINE=true
  --env RUSTUP_TOOLCHAIN=1.75.0
  --env SOURCE_DATE_EPOCH="$SOURCE_DATE_EPOCH_PIN"
  --workdir /work "$IMAGE_ID"
  /bin/bash --noprofile --norc /work/scripts/verify-container-command.sh)

echo "== (1-3) KAT + handshake + policy funnel + R-A4 surface + R-S7 frame/decompress (pinned 1.75) =="
"${RUN[@]}" cargo test -p pake -p cpace_it -p config_it -p surface_it -p compress_it -p address_it --color never

# (3b) The complete module first runs under the ordinary non-root authority. The two cases that must
# create a foreign-owned directory are then compiled non-root, copied/hash-checked into private state,
# and executed by exact name in isolated root containers with no writable host mount and only
# CAP_CHOWN/CAP_FOWNER. The harness-required environment makes a root or POSIX-ACL skip a hard failure.
echo "== (3b) IPC parent-dir hardening behavior tests (R-S11a/R-S11a(b), split authority) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config ipc::ipc_fs::tests --color never
ROOT_IPC_MESSAGES="$VERIFY_TMP/root-ipc-build.json"
"${RUN[@]}" cargo test --lib --features linux-pkg-config --no-run --message-format=json --color never \
  >"$ROOT_IPC_MESSAGES"
chmod 0600 "$ROOT_IPC_MESSAGES"
ROOT_IPC_ARTIFACT="$VERIFY_TMP/root-ipc-test"
/usr/bin/python3 -I -S scripts/prepare-root-ipc-test.py \
  --messages "$ROOT_IPC_MESSAGES" \
  --target-root "$VERIFY_TARGET" \
  --output "$ROOT_IPC_ARTIFACT"

run_root_ipc_test() {
  local test_name="$1" label="$2" output error status
  output="$VERIFY_TMP/root-ipc-$label.out"
  error="$VERIFY_TMP/root-ipc-$label.err"
  set +e
  "$DOCKER_BIN" run --rm --pull=never --network=none --read-only \
    --user 0:0 \
    --cap-drop=ALL --cap-add=CHOWN --cap-add=FOWNER \
    --security-opt=no-new-privileges \
    --pids-limit=64 --memory=1g --memory-swap=1g --cpus=1 \
    --tmpfs /tmp:rw,exec,nosuid,nodev,mode=1777,size=128m \
    --mount "type=bind,source=$ROOT_IPC_ARTIFACT,target=/root-ipc-test,readonly" \
    --env RUSTDESK_ROOT_IPC_FS_HARNESS=1 \
    "$IMAGE_ID" /root-ipc-test "$test_name" --exact --nocapture --test-threads=1 \
    >"$output" 2>"$error"
  status=$?
  set -e
  [ "$status" -eq 0 ] || { echo "verify: root IPC test failed: $test_name" >&2; cat "$output" "$error" >&2; exit 1; }
  [ "$(stat -c '%s' "$output")" -le 65536 ] && [ "$(stat -c '%s' "$error")" -le 65536 ] \
    || { echo "verify: root IPC test output exceeded its bound" >&2; exit 1; }
  ! grep -qi 'skip' "$output" "$error" \
    || { echo "verify: root IPC test skipped required behavior: $test_name" >&2; exit 1; }
  [ "$(grep -c '^running 1 test$' "$output")" -eq 1 ] \
    && [ "$(grep -cF "test $test_name ... ok" "$output")" -eq 1 ] \
    && [ "$(grep -cE '^test result: ok[.] 1 passed; 0 failed; 0 ignored; 0 measured; [0-9]+ filtered out; finished in ' "$output")" -eq 1 ] \
    || { echo "verify: root IPC test result is not the exact one-test verdict: $test_name" >&2; cat "$output" "$error" >&2; exit 1; }
}
run_root_ipc_test \
  ipc::ipc_fs::tests::test_ensure_secure_ipc_parent_dir_recreates_foreign_service_dir recreate
run_root_ipc_test \
  ipc::ipc_fs::tests::test_ensure_secure_ipc_parent_dir_foreign_nonempty_fails_closed nonempty

# (3b-i) IPC service-socket peer-uid AUTHORIZATION policy (R-S11a / §17 root box): the Linux `_service`
# IPC socket is 0666 (world-connectable so the active non-root user process can reach it), gated at
# accept-time by is_allowed_service_peer_uid — admits ONLY root (SO_PEERCRED uid 0) or the active-session
# uid, and FAIL-CLOSED (root-only) when active_uid is unknown — backed by a /proc/pid/exe match against
# the current binary. test_service_peer_uid_policy pins that boundary; it lives in `ipc::ipc_auth::tests`,
# which the `ipc::ipc_fs::tests` filter above does NOT match, so it was previously UNGATED. Gate it so the
# local-privilege-escalation boundary on the root box cannot silently regress (the win/macos peer-policy
# tests in the same module are cfg-compiled out on this Linux build and simply filter out).
echo "== (3b-i) IPC service-socket peer-uid authorization policy (R-S11a/§17) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config ipc::ipc_auth::tests --color never

# (3b-i-r) R-G6/R-SV4 relay-route compatibility helper: it must be an identity
# transform, never a suffix stripper. This pins the Rust-side defense in depth
# for stale generated bridge or native callers.
echo "== (3b-i-r) relay-route suffix identity test (R-G6/R-SV4) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config ui_interface::relay_route_tests --color never

# (3b-iv) R-A4/R-X4/R-S11b-3: the rendezvous trust anchor (get_key) must return the baked RS_PUB_KEY,
# and the legacy "key" option must not persist at all. Upstream re-pointed the client via
# Config::get_option("key") / the async IPC options blob / the Windows license; the fork pins the option
# empty and reads NO override.
echo "== (3b-iv) trust-anchor option is pinned empty and get_key is constant (R-A4/R-X4/R-S11b-3) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config common::tests::get_key_uses_pinned_anchor_and_rejects_option_override --color never

echo "== (3b-iv-a) custom-client app-name is a constrained system identifier (R-S11d-26) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config common::tests::custom_client_app_name_identifier_contract --color never

# (3b-iii) R-S11/R-S11g: ordinary main IPC is a closed, capped, one-request protocol. Password
# values use separate raw endpoints with fixed canonical frames, proof-before-body admission, and
# operation-bound finality; they are not variants of the serde/main/service protocols.
echo "== (3b-iii) bounded closed main IPC transactions (R-S11/R-S11g) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config ipc::test::main_protocol_rejects_global_data_frames --color never
"${RUN[@]}" cargo test --lib --features linux-pkg-config ipc::test::main_authority_keeps_service_owned_mutations_closed --color never
"${RUN[@]}" cargo test --lib --features linux-pkg-config ipc::test::privileged_and_main_connections_use_bounded_frame_codecs --color never
"${RUN[@]}" cargo test --lib --features linux-pkg-config ipc::password::tests --color never
"${RUN[@]}" cargo test -p hbb_common --lib config::tests::test_get_id_is_side_effect_free --color never
"${RUN[@]}" cargo test -p hbb_common --lib config::tests::test_get_salt_is_side_effect_free --color never
"${RUN[@]}" cargo test -p hbb_common --lib config::tests::test_load_does_not_generate_id_for_empty_config --color never
"${RUN[@]}" cargo test -p hbb_common --lib config::tests::test_load_reads_legacy_plaintext_id_without_storing --color never
"${RUN[@]}" cargo test -p hbb_common --lib config::tests::test_store_clears_empty_id_storage --color never
