if verify_scan_capture "$VERIFY_TMP/r_s11e23_legacy_registry" -nE 'get_uninstall_registry_subkey|get_install_info|get_reg_of|Wow6432Node|54E86BC2-6C85-41F3-A9EB-1A94AC9B1F93|_is1' src/platform/windows.rs; then
  r_s11e23="$r_s11e23 legacy-uninstall-registry-authority-present:$(tr '\n' ';' <"$VERIFY_TMP/r_s11e23_legacy_registry")"
fi
grep -qF 'Windows legacy uninstall-registry metadata selected current service policy' requirements.html || r_s11e23="$r_s11e23 requirements-disposition-missing"
grep -qF 'R-S11e-23 — Windows current-package registry authority' HARDENING_STATUS.md  || r_s11e23="$r_s11e23 hardening-ledger-missing"
if [ -n "$r_s11e23" ]; then echo "  FAIL R-S11e-23 Windows current-package registry authority:$r_s11e23"; rc=1; else
  echo "  ok  R-S11e-23 installed-state and service-owned RDP policy use only the current MSI product's explicit 64-bit HKLM namespace and fixed non-reparse executable root"; fi

# (3b-iii-d3) R-S11j/R-S11e-24: privacy-mode display recovery is a same-process snapshot,
# not a generic config record that an elevated --server can reinterpret as an arbitrary HKLM write.
echo "== (3b-iii-d3) Windows privacy-display recovery authority (R-S11j/R-S11e-24) =="
r_s11e24=
reg_recovery_module=$(awk '/pub\(crate\) mod reg_display_settings/,/^}/' src/platform/windows.rs)
reg_recovery_struct=$(awk '/pub\(crate\) struct RegRecovery/,/^    }/' src/platform/windows.rs)
reg_recovery_read=$(awk '/pub\(crate\) fn read_reg_connectivity/,/^    }/' src/platform/windows.rs)
reg_recovery_restore_one=$(awk '/fn restore_one_reg_connectivity/,/^    }/' src/platform/windows.rs)
reg_recovery_restore_all=$(awk '/pub\(crate\) fn restore_reg_connectivity/,/^    }/' src/platform/windows.rs)
grep -qF 'pub(crate) mod reg_display_settings {' src/platform/windows.rs              || r_s11e24="$r_s11e24 recovery-module-not-crate-private"
grep -qF 'subkey: String,' <<<"$reg_recovery_struct"                                 || r_s11e24="$r_s11e24 enumerated-subkey-field-missing"
grep -qF 'old_recent: RegValue,' <<<"$reg_recovery_struct"                           || r_s11e24="$r_s11e24 process-snapshot-field-missing"
grep -qF 'const REG_GRAPHICS_DRIVERS_PATH: &str = "SYSTEM\\CurrentControlSet\\Control\\GraphicsDrivers";' src/platform/windows.rs || r_s11e24="$r_s11e24 fixed-graphicsdrivers-parent-missing"
grep -qF 'const REG_CONNECTIVITY_PATH: &str = "Connectivity";' src/platform/windows.rs || r_s11e24="$r_s11e24 fixed-connectivity-parent-missing"
grep -qF 'const REG_RECENT_VALUE: &str = "Recent";' src/platform/windows.rs           || r_s11e24="$r_s11e24 fixed-recent-value-missing"
grep -qF "subkey.contains('\\\\')" <<<"$reg_recovery_module"                       || r_s11e24="$r_s11e24 nested-subkey-rejection-missing"
grep -qF 'subkey.chars().any(|value| value.is_control())' <<<"$reg_recovery_module"  || r_s11e24="$r_s11e24 control-subkey-rejection-missing"
grep -qF 'subkey.encode_utf16().count() > MAX_REGISTRY_SUBKEY_NAME_UTF16' <<<"$reg_recovery_module" || r_s11e24="$r_s11e24 subkey-length-bound-missing"
grep -qF 'reg_item.get_raw_value(REG_RECENT_VALUE)' <<<"$reg_recovery_read"          || r_s11e24="$r_s11e24 fixed-recent-snapshot-read-missing"
grep -qF 'Err(err) if err.kind() == ErrorKind::NotFound => {}' <<<"$reg_recovery_read" || r_s11e24="$r_s11e24 absent-value-policy-missing"
if grep -qF 'enum_values()' <<<"$reg_recovery_read"; then
  r_s11e24="$r_s11e24 overbroad-connectivity-value-read-present"
fi
grep -qF 'let path = connectivity_subkey_path(&reg_recovery.subkey)?;' <<<"$reg_recovery_restore_one" || r_s11e24="$r_s11e24 restore-target-not-internally-derived"
grep -qF 'hklm.open_subkey_with_flags(path, KEY_SET_VALUE)?' <<<"$reg_recovery_restore_one" || r_s11e24="$r_s11e24 least-privilege-fixed-target-open-missing"
grep -qF 'reg_item.set_raw_value(REG_RECENT_VALUE, &reg_recovery.old_recent)?;' <<<"$reg_recovery_restore_one" || r_s11e24="$r_s11e24 fixed-recent-snapshot-write-missing"
grep -qF 'for recovery in recoveries {' <<<"$reg_recovery_restore_all"               || r_s11e24="$r_s11e24 all-recoveries-not-attempted"
grep -qF 'reg_recoveries: Vec<reg_display_settings::RegRecovery>' src/privacy_mode/win_virtual_display.rs || r_s11e24="$r_s11e24 process-local-owner-missing"
grep -qF 'std::mem::take(&mut self.reg_recoveries)' src/privacy_mode/win_virtual_display.rs || r_s11e24="$r_s11e24 recoveries-not-consumed-once"
grep -qF 'connectivity_recovery_contains_only_enumerated_subkey_and_snapshot' src/platform/windows.rs || r_s11e24="$r_s11e24 fixed-target-test-missing"
grep -qF 'connectivity_recovery_rejects_invalid_subkeys' src/platform/windows.rs || r_s11e24="$r_s11e24 invalid-subkey-test-missing"
grep -qF 'connectivity_subkey_path(&"x".repeat(256)).is_err()' src/platform/windows.rs || r_s11e24="$r_s11e24 overlong-subkey-test-missing"
grep -qF 'connectivity_recovery_retains_every_changed_subkey' src/platform/windows.rs || r_s11e24="$r_s11e24 multi-display-recovery-test-missing"
if printf '%s\n' "$reg_recovery_struct" | grep -Eq '^[[:space:]]*(path|key|new|changed|changed_recent):|\(Vec<u8>,[[:space:]]*isize\)'; then
  r_s11e24="$r_s11e24 caller-selected-registry-target-or-type-field-present"
fi
if printf '%s\n' "$reg_recovery_module" | grep -Eq 'Serialize|Deserialize|serde_json|isize_to_reg_type'; then
  r_s11e24="$r_s11e24 serialized-or-caller-selected-registry-type-recovery-present"
fi
if verify_scan_capture "$VERIFY_TMP/r_s11e24_config_replay" -nE 'CONFIG_KEY_REG_RECOVERY|"reg_recovery"|serde_json|Config::(get|set)_option' src/privacy_mode/win_virtual_display.rs; then
  r_s11e24="$r_s11e24 generic-config-recovery-present:$(tr '\n' ';' <"$VERIFY_TMP/r_s11e24_config_replay")"
fi
if grep -Eq 'restore_reg_connectivity|reg_recovery' src/core_main.rs src/privacy_mode.rs; then
  r_s11e24="$r_s11e24 startup-or-exported-recovery-replay-present"
fi
grep -qF 'R-S11j' requirements.html                                                  || r_s11e24="$r_s11e24 normative-requirement-missing"
grep -qF 'Windows privacy-display recovery serialized an arbitrary elevated HKLM write' requirements.html || r_s11e24="$r_s11e24 appendix-disposition-missing"
grep -qF '<tr><td>132</td>' requirements.html                                        || r_s11e24="$r_s11e24 appendix-row-missing"
grep -qF 'R-S11e-24 — Windows privacy-display registry recovery authority' HARDENING_STATUS.md || r_s11e24="$r_s11e24 hardening-ledger-missing"
if [ -n "$r_s11e24" ]; then echo "  FAIL R-S11e-24 Windows privacy-display recovery authority:$r_s11e24"; rc=1; else
  echo "  ok  R-S11e-24 privacy display recovery is a process-local fixed-target snapshot collection; serialized/config/startup arbitrary HKLM replay is absent"; fi

# (3b-iii-d4) R-S11k/R-S11e-25: Linux service-owned roles choose their credential/config
# namespace from the effective uid's passwd record, not ambient HOME/XDG_CONFIG_HOME inherited
# from a particular init manager, sudo policy, or manual launcher.
echo "== (3b-iii-d4) Linux service-owned config-root authority (R-S11k/R-S11e-25) =="
"${RUN[@]}" cargo test --offline --locked -p hbb_common --lib linux_service_owned_config_root --color never
r_s11e25=
config_get_home=$(awk '/pub fn get_home\(\) -> PathBuf {/,/pub fn initialize_windows_service_owned_root/' libs/hbb_common/src/config.rs)
config_service_root=$(awk '/fn initialize_linux_service_owned_root_from_home/,/pub fn path<P: AsRef<Path>>/' libs/hbb_common/src/config.rs)
config_path=$(awk '/pub fn path<P: AsRef<Path>>/,/pub fn log_path\(\)/' libs/hbb_common/src/config.rs)
core_service_bootstrap=$(awk '/pub fn core_main\(\) -> Option<Vec<String>> {/,/let mut args = Vec::new\(\);/' src/core_main.rs)
service_child_launch=$(awk '/fn try_start_server_\(/,/    let executable_fd = child_executable/' src/platform/linux.rs)
root_child_env=$(awk '/^        None => \{/,/^        \}/' <<<"$service_child_launch")
grep -qF 'static LINUX_SERVICE_OWNED_CONFIG_ROOT: OnceLock<LinuxServiceOwnedConfigRoot>' libs/hbb_common/src/config.rs || r_s11e25="$r_s11e25 process-root-once-cell-missing"
grep -qF 'linux_service_owned_config_root()' <<<"$config_get_home"                || r_s11e25="$r_s11e25 get-home-does-not-consume-service-root"
grep -qF 'return root.home.clone();' <<<"$config_get_home"                         || r_s11e25="$r_s11e25 get-home-does-not-return-trusted-home"
grep -qF 'linux_service_owned_config_root()' <<<"$config_path"                    || r_s11e25="$r_s11e25 config-path-does-not-consume-service-root"
grep -qF 'let mut path = root.path.clone();' <<<"$config_path"                     || r_s11e25="$r_s11e25 config-path-does-not-return-service-root"
grep -qF 'crate::platform::linux::get_effective_home_dir_trusted()' <<<"$config_service_root" || r_s11e25="$r_s11e25 effective-passwd-home-lookup-missing"
grep -qF 'get_home_dir_for_uid_trusted(get_effective_uid())' libs/hbb_common/src/platform/linux.rs || r_s11e25="$r_s11e25 effective-uid-home-helper-missing"
grep -qF 'Linux service-owned config home is unavailable' <<<"$config_service_root" || r_s11e25="$r_s11e25 missing-passwd-home-not-fail-closed"
grep -qF 'Linux service-owned config root was initialized inconsistently' <<<"$config_service_root" || r_s11e25="$r_s11e25 inconsistent-reinitialization-not-rejected"
grep -qF 'let service_supervisor_role = crate::common::current_service_supervisor_role();' <<<"$core_service_bootstrap" || r_s11e25="$r_s11e25 service-supervisor-classifier-missing"
grep -qF 'if service_supervisor_role == crate::common::ServiceSupervisorRole::Malformed {' <<<"$core_service_bootstrap" || r_s11e25="$r_s11e25 malformed-service-supervisor-not-rejected"
grep -qF 'let linux_service_owned_config_role = service_supervisor_role' <<<"$core_service_bootstrap" || r_s11e25="$r_s11e25 service-owned-config-role-missing"
grep -qF '== crate::common::ServiceSupervisorRole::Exact' <<<"$core_service_bootstrap" || r_s11e25="$r_s11e25 exact-service-supervisor-role-missing"
grep -qF '|| crate::common::is_service_owned_server_process();' <<<"$core_service_bootstrap" || r_s11e25="$r_s11e25 exact-service-child-role-missing"
bootstrap_load_line=$(grep -nF 'crate::load_custom_client();' <<<"$core_service_bootstrap" | cut -d: -f1)
bootstrap_root_line=$(grep -nF 'Config::initialize_linux_service_owned_root()' <<<"$core_service_bootstrap" | cut -d: -f1)
if [ -z "$bootstrap_load_line" ] || [ -z "$bootstrap_root_line" ] || [ "$bootstrap_load_line" -ge "$bootstrap_root_line" ]; then
  r_s11e25="$r_s11e25 service-root-not-after-signed-app-identity"
fi
grep -qF 'Linux service-owned config authority failed closed' <<<"$core_service_bootstrap" || r_s11e25="$r_s11e25 service-root-init-not-fail-closed"
grep -qF '.env_clear()' <<<"$service_child_launch"                                  || r_s11e25="$r_s11e25 service-child-environment-not-cleared"
grep -qF 'hbb_common::platform::linux::get_effective_home_dir_trusted()' <<<"$root_child_env" || r_s11e25="$r_s11e25 root-child-effective-passwd-home-missing"
grep -qF 'command.env("HOME", trusted_home);' <<<"$root_child_env"                || r_s11e25="$r_s11e25 root-child-trusted-home-not-exported"
if [ "$(grep -oF '"HOME"' <<<"$root_child_env" | wc -l)" -ne 1 ]; then
  r_s11e25="$r_s11e25 root-child-ambient-home-copy-present"
fi
if grep -qF 'XDG_CONFIG_HOME' <<<"$root_child_env"; then
  r_s11e25="$r_s11e25 root-child-xdg-config-home-present"
fi
grep -qF 'linux_service_owned_config_root_ignores_ambient_home_and_xdg' libs/hbb_common/src/config.rs || r_s11e25="$r_s11e25 ambient-root-regression-test-missing"
grep -qF '/tmp/rustdesk-attacker-selected-home' libs/hbb_common/src/config.rs         || r_s11e25="$r_s11e25 hostile-home-fixture-missing"
grep -qF '/tmp/rustdesk-attacker-selected-xdg' libs/hbb_common/src/config.rs          || r_s11e25="$r_s11e25 hostile-xdg-fixture-missing"
grep -qF '<span class="id">R-S11k</span>' requirements.html                        || r_s11e25="$r_s11e25 normative-requirement-missing"
grep -qF 'Linux service-owned configuration followed ambient HOME/XDG_CONFIG_HOME' requirements.html || r_s11e25="$r_s11e25 appendix-disposition-missing"
grep -qF '<tr><td>133</td>' requirements.html                                        || r_s11e25="$r_s11e25 appendix-row-missing"
grep -qF 'R-S11e-25 — Linux service-owned config-root authority' HARDENING_STATUS.md || r_s11e25="$r_s11e25 hardening-ledger-missing"
if [ -n "$r_s11e25" ]; then echo "  FAIL R-S11e-25 Linux service-owned config-root authority:$r_s11e25"; rc=1; else
  echo "  ok  R-S11e-25 Linux service-owned roles bind Config home/path to the effective uid's passwd home before first config access; ambient HOME/XDG_CONFIG_HOME remains user-mode-only authority"; fi

# (3b-iii-d5) R-S11l/R-S11e-26: the root service child uses the selected desktop
# snapshot as its session environment authority. Ambient supervisor variables never
# re-enter the child after env_clear, and privilege selection is independent of the
# desktop snapshot passed to the launcher.
echo "== (3b-iii-d5) Linux service-child environment authority (R-S11l/R-S11e-26) =="
r_s11e26=
service_launch=$(awk '/fn try_start_server_\(/,/fn stop_unregistered_service_child/' src/platform/linux.rs)
service_loop=$(awk '/pub fn start_os_service\(\)/,/^}/' src/platform/linux.rs)
term_fallback=$(awk '/fn suggest_best_term\(\)/,/^}/' src/platform/linux.rs)
grep -qF 'enum ServiceChildPrincipal {' src/platform/linux.rs                         || r_s11e26="$r_s11e26 typed-principal-selection-missing"
grep -qF 'ServiceChildPrincipal::RootService' <<<"$service_loop"                     || r_s11e26="$r_s11e26 root-principal-call-missing"
grep -qF 'ServiceChildPrincipal::ActiveDesktopUser' <<<"$service_loop"               || r_s11e26="$r_s11e26 active-user-principal-call-missing"
if [ "$(grep -oF '&desktop,' <<<"$service_loop" | wc -l)" -lt 2 ]; then
  r_s11e26="$r_s11e26 selected-desktop-not-passed-to-both-principals"
fi
if grep -qF 'start_server(None' src/platform/linux.rs; then
  r_s11e26="$r_s11e26 root-launch-discards-desktop"
fi
for binding in \
  'insert_nonempty_env(&mut command, "DISPLAY", &desktop.display);' \
  'insert_nonempty_env(&mut command, "XAUTHORITY", &desktop.xauth);' \
  'insert_nonempty_env(&mut command, "WAYLAND_DISPLAY", &desktop.wl_display);' \
  'insert_nonempty_env(&mut command, "DBUS_SESSION_BUS_ADDRESS", &desktop.dbus);'; do
  grep -qF "$binding" <<<"$service_launch" || r_s11e26="$r_s11e26 selected-desktop-binding-missing"
done
if grep -Eq 'std::env::(var|var_os|set_var)\(' <<<"$service_launch"; then
  r_s11e26="$r_s11e26 ambient-service-environment-read-present"
fi
if grep -Eq 'PULSE_LATENCY_MSEC|PIPEWIRE_LATENCY' <<<"$service_launch"; then
  r_s11e26="$r_s11e26 ambient-audio-environment-copy-present"
fi
if grep -Eq 'std::env::|TMUX|STY|screen-256color' <<<"$term_fallback"; then
  r_s11e26="$r_s11e26 terminal-fallback-uses-ambient-supervisor-state"
fi
if verify_scan_capture "$VERIFY_TMP/rd_verify_r_s11e26_ambient_mutation" \
  -nE 'fn set_x11_env|std::env::set_var\("(DISPLAY|XAUTHORITY)"' src/platform/linux.rs; then
  cat "$VERIFY_TMP/rd_verify_r_s11e26_ambient_mutation"
  r_s11e26="$r_s11e26 process-global-session-environment-mutation-present"
fi
for hostile in \
  'DISPLAY=attacker.invalid:99' \
  'XAUTHORITY=/tmp/rustdesk-attacker.Xauthority' \
  'WAYLAND_DISPLAY=rustdesk-attacker-wayland' \
  'DBUS_SESSION_BUS_ADDRESS=unix:path=/tmp/rustdesk-attacker-dbus' \
  'PULSE_LATENCY_MSEC=31337' \
  'PIPEWIRE_LATENCY=31337/31337'; do
  grep -qF "$hostile" scripts/smoke-service-lifecycle.sh || r_s11e26="$r_s11e26 hostile-runtime-fixture-incomplete"
done
grep -qF 'root service child environment escaped its bounded allowlist' scripts/smoke-service-lifecycle.sh || r_s11e26="$r_s11e26 root-runtime-allowlist-not-enforced"
grep -qF 'root service child adopted a hostile ambient environment value' scripts/smoke-service-lifecycle.sh || r_s11e26="$r_s11e26 hostile-runtime-value-not-rejected"
grep -qF 'SERVICE_LIFECYCLE_ROOT_ENVIRONMENT=pass authority=desktop-snapshot ambient=excluded' scripts/smoke-service-lifecycle.sh || r_s11e26="$r_s11e26 runtime-result-marker-missing"
grep -qF 'FAIL R-S11e-26: root service child did not reject the hostile ambient launch environment' scripts/smoke-server.sh || r_s11e26="$r_s11e26 mandatory-smoke-consumer-missing"
grep -qF '<span class="id">R-S11l</span>' requirements.html                        || r_s11e26="$r_s11e26 normative-requirement-missing"
grep -qF 'Linux root service child re-imported ambient session/audio environment' requirements.html || r_s11e26="$r_s11e26 appendix-disposition-missing"
grep -qF '<tr><td>134</td>' requirements.html                                       || r_s11e26="$r_s11e26 appendix-row-missing"
grep -qF 'R-S11e-26 — Linux service-child environment authority' HARDENING_STATUS.md || r_s11e26="$r_s11e26 hardening-ledger-missing"
if [ -n "$r_s11e26" ]; then echo "  FAIL R-S11e-26 Linux service-child environment authority:$r_s11e26"; rc=1; else
  echo "  ok  R-S11e-26 root and active-user children receive the selected desktop snapshot under a typed principal choice; hostile ambient session/audio variables cannot re-enter after env_clear"; fi

# (3b-iii-d6) R-S11m/R-S11e-27: Linux service-owned roles do not inherit pathname
# authority from a manual/sudo/init launcher working directory. Custom-client sidecars
# are executable-relative on every build, and both supervisor and child run from '/'.
echo "== (3b-iii-d6) Linux service-owned working-directory authority (R-S11m/R-S11e-27) =="
"${RUN[@]}" cargo test --offline --locked --lib --features linux-pkg-config common::tests::custom_client_config_is_executable_relative --color never
r_s11e27=
custom_client_loader=$(awk '/pub fn load_custom_client\(\)/,/fn read_custom_client_advanced_settings/' src/common.rs)
core_service_bootstrap=$(awk '/pub fn core_main\(\) -> Option<Vec<String>> {/,/let mut args = Vec::new\(\);/' src/core_main.rs)
service_child_launch=$(awk '/fn try_start_server_\(/,/fn stop_unregistered_service_child/' src/platform/linux.rs)
grep -qF 'std::env::current_exe()' <<<"$custom_client_loader"                     || r_s11e27="$r_s11e27 custom-loader-executable-source-missing"
grep -qF 'custom_client_config_path(&executable)' <<<"$custom_client_loader"       || r_s11e27="$r_s11e27 custom-loader-path-helper-missing"
grep -qF 'if !executable.is_absolute()' <<<"$custom_client_loader"                 || r_s11e27="$r_s11e27 custom-loader-absolute-path-check-missing"
grep -qF 'Some(path.join("custom.txt"))' <<<"$custom_client_loader"               || r_s11e27="$r_s11e27 custom-loader-sidecar-path-missing"
if grep -qF 'debug_assertions' <<<"$custom_client_loader" \
  || grep -qF '"./custom.txt"' <<<"$custom_client_loader" \
  || grep -qF 'current_dir(' <<<"$custom_client_loader"; then
  r_s11e27="$r_s11e27 ambient-custom-loader-present"
fi
grep -qF 'fn custom_client_config_is_executable_relative()' src/common.rs           || r_s11e27="$r_s11e27 executable-relative-regression-test-missing"
grep -qF 'const LINUX_SERVICE_OWNED_WORKING_DIRECTORY: &str = "/";' src/core_main.rs || r_s11e27="$r_s11e27 fixed-service-working-directory-missing"
grep -qF 'std::env::set_current_dir(LINUX_SERVICE_OWNED_WORKING_DIRECTORY)' <<<"$core_service_bootstrap" || r_s11e27="$r_s11e27 supervisor-working-directory-bind-missing"
grep -qF 'Linux service-owned working-directory authority failed closed' <<<"$core_service_bootstrap" || r_s11e27="$r_s11e27 supervisor-working-directory-not-fail-closed"
working_directory_line=$(grep -nF 'std::env::set_current_dir(LINUX_SERVICE_OWNED_WORKING_DIRECTORY)' <<<"$core_service_bootstrap" | cut -d: -f1)
global_init_line=$(grep -nF 'crate::common::global_init()' <<<"$core_service_bootstrap" | cut -d: -f1)
custom_load_line=$(grep -nF 'crate::load_custom_client();' <<<"$core_service_bootstrap" | cut -d: -f1)
if [ -z "$working_directory_line" ] || [ -z "$global_init_line" ] || [ -z "$custom_load_line" ] \
  || [ "$working_directory_line" -ge "$global_init_line" ] || [ "$working_directory_line" -ge "$custom_load_line" ]; then
  r_s11e27="$r_s11e27 supervisor-working-directory-bind-too-late"
fi
grep -qF '.current_dir("/")' <<<"$service_child_launch"                           || r_s11e27="$r_s11e27 child-working-directory-bind-missing"
child_cwd_line=$(grep -nF '.current_dir("/")' <<<"$service_child_launch" | cut -d: -f1)
child_spawn_line=$(grep -nF 'let spawn_result = command.spawn();' <<<"$service_child_launch" | cut -d: -f1)
if [ -z "$child_cwd_line" ] || [ -z "$child_spawn_line" ] || [ "$child_cwd_line" -ge "$child_spawn_line" ]; then
  r_s11e27="$r_s11e27 child-working-directory-bind-too-late"
fi
for runtime_proof in \
  'readonly HOSTILE_SERVICE_CWD=/tmp/rustdesk-attacker-cwd' \
  '%%%not-a-signed-custom-client%%%' \
  'service supervisor retained its launcher working directory' \
  'service child retained its supervisor working directory' \
  'service consumed custom.txt from its hostile launcher directory' \
  'SERVICE_LIFECYCLE_WORKING_DIRECTORY=pass supervisor=/ child=/ ambient=excluded'; do
  grep -qF "$runtime_proof" scripts/smoke-service-lifecycle.sh || r_s11e27="$r_s11e27 hostile-runtime-proof-missing"
done
