# (3b-iii-d9c) R-S11ab/R-S11e-42: the exact active logind
# session remains the sole authority for the local X11 endpoint, and a
# process-derived credential hint must describe that same endpoint.
echo "== (3b-iii-d9c) Linux selected X11 session display authority (R-S11ab/R-S11e-42) =="
"${RUN[@]}" cargo test -p hbb_common --lib r_s11e42_ --color never
"${RUN[@]}" cargo test --lib --features linux-pkg-config r_s11e42_ --color never
r_s11e42=
x11_logind_authority=$(awk '/fn parse_local_x_display_name/,/pub fn get_values_of_seat0/' libs/hbb_common/src/platform/linux.rs)
x11_loginctl_vocabulary=$(awk '/enum LoginctlProperty/,/enum LoginctlQuery/' libs/hbb_common/src/platform/linux.rs)
x11_environment_authority=$(awk '/fn xauthority_from_environ_for_display/,/fn get_env\(/' src/platform/linux.rs)
x11_desktop_authority=$(awk '/fn get_display_x11/,/pub fn refresh/' src/platform/linux.rs)
x11_refresh_authority=$(awk '/pub fn refresh\(&mut self\)/,/    #\[cfg\(test\)\]/' src/platform/linux.rs)
x11_shared_tests=$(awk '/fn r_s11e42_x11_display_names_are_local_and_canonical/,/fn r_s11e40_session_display_fallback_is_binary_owned/' libs/hbb_common/src/platform/linux.rs)
x11_root_tests=$(awk '/fn r_s11e42_xauthority_is_bound_to_the_selected_display/,/^}/' src/platform/linux.rs)
for binding in \
  'Display,' \
  'Self::Display => "Display"' \
  'Self::Display => "--property=Display"'; do
  grep -qF "$binding" <<<"$x11_loginctl_vocabulary" || r_s11e42="$r_s11e42 typed-display-property-missing"
done
for binding in \
  "display.strip_prefix(':')" \
  "components.next()?.parse::<u32>().ok()?" \
  'format!(":{display_number}.{screen_number}")' \
  'pub fn local_x_display_names_share_server' \
  '(Some((left, _)), Some((right, _))) if left == right' \
  'loginctl_session_properties(session, &[LoginctlProperty::Display])' \
  '.and_then(|display| normalize_local_x_display_name(&display))'; do
  grep -qF "$binding" <<<"$x11_logind_authority" || r_s11e42="$r_s11e42 exact-session-display-binding-missing"
done
for binding in \
  'let observed_display = proc_environ_value(environ, "DISPLAY")?;' \
  '!local_x_display_names_share_server(&observed_display, display)' \
  'let xauthority = proc_environ_value(environ, "XAUTHORITY")?;' \
  'xauthority.bytes().any(|byte| byte.is_ascii_control())' \
  '!Path::new(&xauthority).is_absolute()' \
  'matching_process_cmdlines(uid, process_pattern)' \
  'xauthority_from_environ_for_display(&environ, display)'; do
  grep -qF "$binding" <<<"$x11_environment_authority" || r_s11e42="$r_s11e42 display-bound-xauthority-missing"
done
for binding in \
  'self.display = get_x11_display_of_session(&self.sid).unwrap_or_default();' \
  'self.xauth.clear();' \
  'if self.display.is_empty() {' \
  'xauthority_from_matching_process(&self.uid, process, &self.display)' \
  'let gdm = format!("/run/user/{}/gdm/Xauthority", self.uid);' \
  'if Path::new(&gdm).is_file()'; do
  grep -qF "$binding" <<<"$x11_desktop_authority" || r_s11e42="$r_s11e42 desktop-display-chain-missing"
done
for binding in \
  'if self.is_wayland() {' \
  'self.get_display_x11();' \
  'self.get_xauth_x11();'; do
  grep -qF "$binding" <<<"$x11_refresh_authority" || r_s11e42="$r_s11e42 retained-session-refresh-missing"
done
grep -qF $'                    self.get_display_x11();\n                    self.get_xauth_x11();' \
  <<<"$x11_refresh_authority" || r_s11e42="$r_s11e42 retained-session-refresh-pair-missing"
if grep -Eq 'get_env\(ENV_KEY_DISPLAY|get_display_by_user|display_from_x11_socket|self\.display = ":0"|\.replace\("localhost"|get_xauth_from_xorg|matching_process_cmdlines\(&self\.uid, "Xorg"\)' <<<"$x11_desktop_authority"; then
  r_s11e42="$r_s11e42 heuristic-display-or-xorg-authority-present"
fi
if grep -Eq 'const W_PATHS|fn w_path\(|get_display_by_user|display_from_x11_socket|x11_socket_(display_name|owner_matches_user)|get_xauth_from_xorg|/tmp/\.X11-unix' src/platform/linux.rs; then
  r_s11e42="$r_s11e42 legacy-display-fallback-present"
fi
for fixture in scripts/smoke-service-loginctl.sh scripts/smoke-debian-systemd-loginctl.sh; do
  grep -qF '"5:--no-pager --property=Display show-session -- 1")' "$fixture" \
    || r_s11e42="$r_s11e42 ${fixture##*/}:display-query-missing"
  grep -qF "'Display=:0'" "$fixture" \
    || r_s11e42="$r_s11e42 ${fixture##*/}:display-result-missing"
done
for test_binding in \
  'fn r_s11e42_x11_display_names_are_local_and_canonical()' \
  'normalize_local_x_display_name(":0007.02")' \
  'local_x_display_names_share_server(":7", ":0007.02")' \
  '"localhost:0"' \
  'fn r_s11e42_xauthority_is_bound_to_the_selected_display()' \
  'xauthority_from_environ_for_display(selected, ":8")' \
  'b"DISPLAY=host:7\0XAUTHORITY=/tmp/remote.auth\0"'; do
  grep -qF "$test_binding" <<<"$x11_shared_tests$x11_root_tests" || r_s11e42="$r_s11e42 focused-regression-missing"
done
grep -qF '<span class="id">R-S11ab</span>' requirements.html || r_s11e42="$r_s11e42 normative-requirement-missing"
grep -qF 'Linux X11 endpoint selection remains bound to the exact active logind session' requirements.html \
  || r_s11e42="$r_s11e42 normative-authority-clause-missing"
grep -qF '<tr><td>150</td>' requirements.html || r_s11e42="$r_s11e42 appendix-row-missing"
grep -qF 'Linux selected X11 session lost endpoint authority' requirements.html || r_s11e42="$r_s11e42 appendix-disposition-missing"
grep -qF 'R-S11e-42 — Linux selected X11 session display authority' HARDENING_STATUS.md || r_s11e42="$r_s11e42 hardening-ledger-missing"
if [ -n "$r_s11e42" ]; then echo "  FAIL R-S11e-42 Linux selected X11 session display authority:$r_s11e42"; rc=1; else
  echo "  ok  R-S11e-42 X11 DISPLAY comes only from the exact selected logind session and process Xauthority hints must describe that endpoint"; fi

# (3b-iii-d9c2) R-S11ac/R-S11e-43: RustDesk no longer owns an
# Xorg child, so process-table text cannot mint root signal authority or
# override the exact selected logind session's headless classification.
echo "== (3b-iii-d9c2) Linux obsolete Xorg process authority (R-S11ac/R-S11e-43) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config r_s11e43_ --color never
r_s11e43=
xorg_headless_authority=$(awk '/pub fn is_headless\(&self\)/,/fn get_display_xauth_wayland/' src/platform/linux.rs)
xorg_headless_test=$(awk '/fn r_s11e43_headless_state_is_derived_from_the_selected_session/,/fn test_desktop_env/' src/platform/linux.rs)
xorg_launcher_history=$(awk '/R-X14 \/ R-S18/,/lazy_static::lazy_static/' src/platform/linux_desktop_manager.rs)
xorg_headless_compact=$(printf '%s' "$xorg_headless_authority" | tr -d '[:space:]')
[ "$xorg_headless_compact" = 'pubfnis_headless(&self)->bool{self.sid.is_empty()}fnget_display_xauth_wayland(&mutself){' ] \
  || r_s11e43="$r_s11e43 headless-not-selected-session-only"
for test_binding in \
  'fn r_s11e43_headless_state_is_derived_from_the_selected_session()' \
  'let mut desktop = Desktop::default();' \
  'assert!(desktop.is_headless());' \
  'desktop.sid = "selected-session".to_owned();' \
  'assert!(!desktop.is_headless());'; do
  grep -qF "$test_binding" <<<"$xorg_headless_test" || r_s11e43="$r_s11e43 focused-regression-missing"
done
grep -qF 'existing-session DISCOVERY only' <<<"$xorg_launcher_history" \
  || r_s11e43="$r_s11e43 launcher-deletion-record-missing"
if grep -Eq 'pam::|std::process::Command|Command::new|try_start_x_session|start_x11|start_xorg' src/platform/linux_desktop_manager.rs; then
  r_s11e43="$r_s11e43 xorg-launch-authority-regressed"
fi
if grep -Eq 'process_is_xorg_with_config|kill_xorg_processes_with_config|is_rustdesk_subprocess|set_is_subprocess|any_process_cmdline_contains|stop_subprocess|format!\("/etc/\{\}/xorg\.conf"' src/platform/linux.rs; then
  r_s11e43="$r_s11e43 obsolete-xorg-process-authority-present"
fi
grep -qF '<span class="id">R-S11ac</span>' requirements.html || r_s11e43="$r_s11e43 normative-requirement-missing"
grep -qF 'Linux service lifecycle never infers Xorg process authority from the global process table' requirements.html \
  || r_s11e43="$r_s11e43 normative-authority-clause-missing"
grep -qF '<tr><td>151</td>' requirements.html || r_s11e43="$r_s11e43 appendix-row-missing"
grep -qF 'Obsolete Linux root-service Xorg process authority' requirements.html \
  || r_s11e43="$r_s11e43 appendix-disposition-missing"
grep -qF 'R-S11e-43 — Linux obsolete Xorg process authority' HARDENING_STATUS.md \
  || r_s11e43="$r_s11e43 hardening-ledger-missing"
if [ -n "$r_s11e43" ]; then echo "  FAIL R-S11e-43 Linux obsolete Xorg process authority:$r_s11e43"; rc=1; else
  echo "  ok  R-S11e-43 no Xorg process text can mint root signal or desktop-state authority; headless state is absence of the exact selected logind session"; fi

# (3b-iii-d9c3) R-S11ad/R-S11e-44: the root supervisor does not
# rediscover no-UI connection managers through mutable process text. The exact
# server parent binds every Linux CM child at spawn and the kernel owns retirement.
echo "== (3b-iii-d9c3) Linux headless CM parent authority (R-S11ad/R-S11e-44) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config r_s11e44_ --color never
r_s11e44=
linux_parent_death_authority=$(awk '/fn arm_linux_child_parent_death/,/fn configure_service_child_pre_exec/' src/platform/linux.rs)
common_parent_bound_launch=$(awk '/pub fn run_me_with_env<T/,/let result = cmd.args\(&args\).spawn/' src/common.rs)
connection_manager_launch=$(awk '/if stream.is_none\(\) \{/,/for _ in 0\.\.20/' src/server/connection.rs)
for binding in \
  'fn arm_linux_child_parent_death' \
  'SYS_prctl' \
  'hbb_common::libc::PR_SET_PDEATHSIG,' \
  'hbb_common::libc::SIGKILL' \
  'SYS_getppid' \
  'actual_parent != hbb_common::libc::c_long::from(expected_parent)' \
  'std::io::Error::from_raw_os_error(hbb_common::libc::ESRCH)' \
  'pub(crate) fn configure_command_kill_on_parent_death' \
  'command.pre_exec(move || arm_linux_child_parent_death(expected_parent))'; do
  grep -qF "$binding" <<<"$linux_parent_death_authority" || r_s11e44="$r_s11e44 parent-death-authority-missing"
done
for binding in \
  'pub(crate) fn run_me_with_env_and_parent_death' \
  'run_me_with_env_inner(args, envs, true)' \
  'if kill_on_parent_death {' \
  'crate::platform::linux::configure_command_kill_on_parent_death(&mut cmd)?;' \
  'hbb_common::platform::linux::configure_command_close_nonstdio_on_exec(&mut cmd)'; do
  grep -qF "$binding" <<<"$common_parent_bound_launch" || r_s11e44="$r_s11e44 production-launch-policy-missing"
done
parent_death_hook_line=$(grep -nF 'configure_command_kill_on_parent_death(&mut cmd)?;' <<<"$common_parent_bound_launch" | head -n1 | cut -d: -f1)
descriptor_hook_line=$(grep -nF 'configure_command_close_nonstdio_on_exec(&mut cmd)' <<<"$common_parent_bound_launch" | head -n1 | cut -d: -f1)
if [ -z "$parent_death_hook_line" ] || [ -z "$descriptor_hook_line" ] || [ "$parent_death_hook_line" -ge "$descriptor_hook_line" ]; then
  r_s11e44="$r_s11e44 parent-death-hook-not-before-descriptor-policy"
fi
connection_manager_launch_compact=$(printf '%s' "$connection_manager_launch" | tr -d '[:space:]')
case "$connection_manager_launch_compact" in
  *'#[cfg(target_os="linux")]letchild=crate::common::run_me_with_env_and_parent_death(args,cm_launch_env())?;#[cfg(any(target_os="macos",target_os="windows"))]letchild=crate::run_me_with_env(args,cm_launch_env())?;'*) ;;
  *) r_s11e44="$r_s11e44 linux-parent-bound-call-site-missing" ;;
esac
for forbidden in \
  'fn stop_headless_connection_manager_processes' \
  'stop_headless_connection_manager_processes();' \
  'fn kill_current_exe_processes_with_arg' \
  'fn kill_process('; do
  if grep -qF "$forbidden" src/platform/linux.rs; then
    r_s11e44="$r_s11e44 global-cm-process-authority-present"
  fi
done
for binding in \
  'fn r_s11e44_linux_parent_bound_child_dies_with_launcher()' \
  'run_me_with_env_and_parent_death(' \
  'SYS_pidfd_open' \
  'parent-bound child survived launcher death'; do
  grep -qF "$binding" src/common.rs || r_s11e44="$r_s11e44 actual-child-regression-missing"
done
grep -qF '<span class="id">R-S11ad</span>' requirements.html || r_s11e44="$r_s11e44 normative-requirement-missing"
grep -qF 'Linux headless connection-manager lifetime is bound at spawn to its exact server parent' requirements.html \
  || r_s11e44="$r_s11e44 normative-authority-clause-missing"
grep -qF '<tr><td>152</td>' requirements.html || r_s11e44="$r_s11e44 appendix-row-missing"
grep -qF 'Linux root-service headless-CM global process authority' requirements.html \
  || r_s11e44="$r_s11e44 appendix-disposition-missing"
grep -qF 'R-S11e-44 — Linux headless connection-manager parent authority' HARDENING_STATUS.md \
  || r_s11e44="$r_s11e44 hardening-ledger-missing"
if [ -n "$r_s11e44" ]; then echo "  FAIL R-S11e-44 Linux headless CM parent authority:$r_s11e44"; rc=1; else
  echo "  ok  R-S11e-44/R-S11e-95 no root process-table sweep owns CMs; every exact Linux server launch arms kernel parent-death authority before exec"; fi

# (3b-iii-d9c3a) R-T4/R-S11c-27t: the per-connection CM bridge may be
# started before the CM endpoint exists. Loss of the owning connection is a
# terminal cancellation signal throughout bootstrap; a closed desktop-ready
# channel is not a wake event that can spin the headless-user loop.
echo "== (3b-iii-d9c3a) Linux CM bootstrap owner-loss cancellation (R-T4/R-S11c-27t) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config cm_startup_lifecycle_tests --color never
r_s11c27t=
cm_startup_lifecycle=$(awk '/enum LinuxDesktopReadyWait \{/,/pub\(crate\) fn cm_launch_token/' src/server/connection.rs)
cm_task_owner=$(awk '/async fn run_cm_ipc_until_owner_closed/,/fn try_start_cm_ipc/' src/server/connection.rs)
cm_task_start=$(awk '/fn try_start_cm_ipc/,/async fn on_message/' src/server/connection.rs)
cm_connection_drop=$(awk '/impl Drop for Connection \{/,/struct LinuxHeadlessHandle/' src/server/connection.rs)
cm_ipc_bootstrap=$(awk '/async fn start_ipc\(/,/\/\/ in case screen is sleep and blank/' src/server/connection.rs)
cm_prelogin_wait=$(awk '/let headless_service_user = loop \{/,/let headless_cm = crate::is_server\(\)/' src/server/connection.rs)
cm_headless_user_wait=$(awk 'index($0, "        if headless_cm {") {capture=1} capture{print} capture && index($0, "let uid = uid_for_username(&username).await?;") {exit}' src/server/connection.rs)
cm_launch_boundary=$(awk '/if stream.is_none\(\) \{/{capture=1} capture{print} /for _ in 0\.\.20 \{/{exit}' src/server/connection.rs)
cm_startup_retry=$(awk '/for _ in 0\.\.20 \{/,/if stream.is_none\(\) \{/' src/server/connection.rs)
for binding in \
  'enum LinuxDesktopReadyWait {' \
  'Wake,' \
  'OwnerClosed,' \
  'Ok(None) => LinuxDesktopReadyWait::OwnerClosed' \
  'Ok(Some(())) | Err(_) => LinuxDesktopReadyWait::Wake' \
  'fn closed_desktop_readiness_is_terminal()' \
  'fn desktop_readiness_signal_remains_a_wake_only()' \
  'fn connection_owner_closure_cancels_pending_cm_bootstrap()' \
  'fn live_connection_allows_cm_bootstrap_completion()' \
  'fn completed_bootstrap_drains_bridge_after_owner_closure()'; do
  grep -qF "$binding" <<<"$cm_startup_lifecycle" || r_s11c27t="$r_s11c27t readiness-lifecycle-binding-missing"
done
for binding in \
  'owner_closed: oneshot::Receiver<()>' \
  'bootstrap_complete: oneshot::Receiver<()>' \
  'F: std::future::Future<Output = T>' \
  'let mut task = Box::pin(task);' \
  'tokio::select! {' \
  'biased;' \
  'result = &mut task => Some(result)' \
  '_ = &mut bootstrap_complete => Some(task.await)' \
  '_ = &mut owner_closed => None'; do
  grep -qF "$binding" <<<"$cm_task_owner" || r_s11c27t="$r_s11c27t task-owner-binding-missing"
done
for binding in \
  'let (bootstrap_complete, bootstrap_completed) = oneshot::channel();' \
  'Self::run_cm_ipc_until_owner_closed(' \
  'p.owner_closed,' \
  'bootstrap_completed,' \
  'bootstrap_complete,' \
  'if let Some(Err(err)) = result'; do
  grep -qF "$binding" <<<"$cm_task_start" || r_s11c27t="$r_s11c27t task-owner-wrapper-missing"
done
[ "$(grep -cF 'owner_closed: oneshot::Receiver<()>' src/server/connection.rs)" = 2 ] \
  || r_s11c27t="$r_s11c27t owner-receiver-topology-invalid"
for binding in \
  'let (cm_ipc_owner, cm_ipc_owner_closed) = oneshot::channel();' \
  'cm_ipc_owner: Option<oneshot::Sender<()>>' \
  'owner_closed: cm_ipc_owner_closed' \
  'cm_ipc_owner: Some(cm_ipc_owner)'; do
  [ "$(grep -cF "$binding" src/server/connection.rs)" = 1 ] \
    || r_s11c27t="$r_s11c27t owner-channel-wiring-invalid"
done
drop_owner_line=$(grep -nF -m 1 'drop(self.cm_ipc_owner.take());' <<<"$cm_connection_drop" | cut -d: -f1)
drop_voice_line=$(grep -nF -m 1 'drop(self.voice_call_input.take());' <<<"$cm_connection_drop" | cut -d: -f1)
drop_cm_line=$(grep -nF -m 1 'self.tx_to_cm.send(ipc::Data::Close)' <<<"$cm_connection_drop" | cut -d: -f1)
if [ -z "$drop_owner_line" ] || [ -z "$drop_voice_line" ] || [ -z "$drop_cm_line" ] \
  || [ "$drop_owner_line" -ge "$drop_voice_line" ] || [ "$drop_voice_line" -ge "$drop_cm_line" ]; then
  r_s11c27t="$r_s11c27t owner-cancellation-not-first-in-drop"
fi
[ "$(grep -cF 'if rx_to_cm.is_closed() {' <<<"$cm_ipc_bootstrap")" = 4 ] \
  || r_s11c27t="$r_s11c27t connection-owner-check-count-invalid"
bootstrap_signal_line=$(grep -nF -m 1 'bootstrap_complete' <<<"$cm_ipc_bootstrap" | cut -d: -f1)
bootstrap_send_line=$(grep -nF -m 1 '.send(())' <<<"$cm_ipc_bootstrap" | cut -d: -f1)
stream_ready_line=$(grep -nF -m 1 'tx_stream_ready.send(()).await' <<<"$cm_ipc_bootstrap" | cut -d: -f1)
live_bridge_line=$(grep -nF -m 1 'let mut cm_file_response_enabled = false;' <<<"$cm_ipc_bootstrap" | cut -d: -f1)
if [ -z "$bootstrap_signal_line" ] || [ -z "$bootstrap_send_line" ] || [ -z "$stream_ready_line" ] || [ -z "$live_bridge_line" ] \
  || [ "$bootstrap_signal_line" -ge "$bootstrap_send_line" ] \
  || [ "$bootstrap_send_line" -ge "$stream_ready_line" ] \
  || [ "$stream_ready_line" -ge "$live_bridge_line" ]; then
  r_s11c27t="$r_s11c27t bootstrap-complete-live-bridge-order-invalid"
fi
prelogin_owner_line=$(grep -nF -m 1 'if rx_to_cm.is_closed() {' <<<"$cm_prelogin_wait" | cut -d: -f1)
prelogin_state_line=$(grep -nF -m 1 'crate::platform::is_headless_no_console_user()' <<<"$cm_prelogin_wait" | cut -d: -f1)
prelogin_sleep_line=$(grep -nF -m 1 'sleep(1.).await;' <<<"$cm_prelogin_wait" | cut -d: -f1)
if [ -z "$prelogin_owner_line" ] || [ -z "$prelogin_state_line" ] || [ -z "$prelogin_sleep_line" ] \
  || [ "$prelogin_owner_line" -ge "$prelogin_state_line" ] \
  || [ "$prelogin_state_line" -ge "$prelogin_sleep_line" ]; then
  r_s11c27t="$r_s11c27t prelogin-owner-cancellation-order-invalid"
fi
headless_owner_line=$(grep -nF -m 1 'if rx_to_cm.is_closed() {' <<<"$cm_headless_user_wait" | cut -d: -f1)
headless_ready_line=$(grep -nF -m 1 'wait_for_linux_desktop_ready(&mut _rx_desktop_ready, 1_000).await' <<<"$cm_headless_user_wait" | cut -d: -f1)
headless_refresh_line=$(grep -nF 'username = linux_desktop_manager::get_username();' <<<"$cm_headless_user_wait" | tail -n1 | cut -d: -f1)
if [ -z "$headless_owner_line" ] || [ -z "$headless_ready_line" ] || [ -z "$headless_refresh_line" ] \
  || [ "$headless_owner_line" -ge "$headless_ready_line" ] \
  || [ "$headless_ready_line" -ge "$headless_refresh_line" ]; then
  r_s11c27t="$r_s11c27t headless-user-cancellation-order-invalid"
fi
for binding in \
  '== LinuxDesktopReadyWait::OwnerClosed' \
  'desktop readiness owner closed before headless connection-manager startup'; do
  grep -qF "$binding" <<<"$cm_headless_user_wait" || r_s11c27t="$r_s11c27t closed-readiness-terminal-branch-missing"
done
launch_owner_line=$(grep -nF -m 1 'connection owner closed before connection-manager launch' <<<"$cm_launch_boundary" | cut -d: -f1)
launch_exec_line=$(grep -nF -m 1 'run_me_with_env_and_parent_death(args, cm_launch_env())?' <<<"$cm_launch_boundary" | cut -d: -f1)
if [ -z "$launch_owner_line" ] || [ -z "$launch_exec_line" ] || [ "$launch_owner_line" -ge "$launch_exec_line" ]; then
  r_s11c27t="$r_s11c27t owner-check-not-before-cm-launch"
fi
retry_owner_line=$(grep -nF -m 1 'connection owner closed while waiting for connection-manager startup' <<<"$cm_startup_retry" | cut -d: -f1)
retry_sleep_line=$(grep -nF -m 1 'sleep(0.3).await;' <<<"$cm_startup_retry" | cut -d: -f1)
if [ -z "$retry_owner_line" ] || [ -z "$retry_sleep_line" ] || [ "$retry_owner_line" -ge "$retry_sleep_line" ]; then
  r_s11c27t="$r_s11c27t owner-check-not-before-cm-retry"
fi
if grep -qF 'let _res = timeout(1_000, _rx_desktop_ready.recv()).await' <<<"$cm_ipc_bootstrap" \
  || grep -qF 'Keep behavior unchanged for now' <<<"$cm_ipc_bootstrap"; then
  r_s11c27t="$r_s11c27t obsolete-closed-readiness-retry-present"
fi
grep -qF 'Every pre-bridge connection-manager wait' requirements.html \
  || r_s11c27t="$r_s11c27t normative-cancellation-clause-missing"
grep -qF 'dedicated per-connection cancellation receiver' requirements.html \
  || r_s11c27t="$r_s11c27t normative-owner-channel-clause-missing"
grep -qF '<tr><td>204</td>' requirements.html || r_s11c27t="$r_s11c27t appendix-row-missing"
grep -qF 'R-S11c-27t/R-T4 — Linux headless CM bootstrap cancellation ownership' HARDENING_STATUS.md \
  || r_s11c27t="$r_s11c27t hardening-ledger-missing"
if [ -n "$r_s11c27t" ]; then echo "  FAIL R-T4/R-S11c-27t Linux CM bootstrap owner-loss cancellation:$r_s11c27t"; rc=1; else
  echo "  ok  R-T4/R-S11c-27t connection-owner loss terminates every CM pre-bridge retry and a closed headless readiness channel cannot spin"; fi

# (3b-iii-d9c4) R-S11ae/R-S11e-45: the final current-image process-table
# consumers are deleted. Selected logind state and the retained Child own
# service replacement; a newly spawned tray performs only its own singleton check.
echo "== (3b-iii-d9c4) Linux current-image lifecycle authority deletion (R-S11ae/R-S11e-45) =="
"${RUN[@]}" cargo test --lib --features linux-pkg-config r_s11e45_ --color never
r_s11e45=
service_replacement_policy=$(awk '/fn service_child_needs_replacement\(/,/fn should_start_server\(/' src/platform/linux.rs)
service_replacement_driver=$(awk '/fn should_start_server\(/,/pub fn start_os_service\(/' src/platform/linux.rs)
