  'std::process::exit(1);' \
  'if !crate::check_process("--tray", true) {' \
  'crate::tray::start_tray();'; do
  grep -qF "$binding" <<<"$tray_receiver" || r_s11e46="$r_s11e46 tray-receiver-principal-boundary-missing"
done
for binding in \
  'fn r_s11e46_linux_tray_requires_non_root_principal()' \
