r_sv4a=""
r_sv4a_relay_state=$(grep -RInE 'force_relay|forceRelay|retry_for_relay|is_force_relay|update_direct' src \
  --include='*.rs' 2>/dev/null | grep -v 'bridge_generated' || true)
[ -z "$r_sv4a_relay_state" ] || r_sv4a="$r_sv4a live-rust-relay-choice-state"
grep -qF 'Ok((stream, "TCP"))' src/client.rs || r_sv4a="$r_sv4a direct-constructor-result-missing"
grep -qF "ResultType<(Stream, &'static str)>" src/client.rs || r_sv4a="$r_sv4a direct-result-type-missing"
grep -qF 'before_first_peer_message: bool' src/client.rs || r_sv4a="$r_sv4a retry-boundary-name-missing"
grep -qF 'direct_only_custom_quality_is_not_relay_capped_before_login' src/client.rs \
  || r_sv4a="$r_sv4a pre-login-quality-regression-missing"
grep -qF 'early_reset_retry_uses_first_peer_message_boundary' src/client.rs \
  || r_sv4a="$r_sv4a retry-boundary-regression-missing"
grep -qF 'let mut limited_fps = min_decode_fps * 9 / 10;' src/client/io_loop.rs \
  || r_sv4a="$r_sv4a direct-fps-policy-missing"
grep -qF 'R-SV4a' requirements.html || r_sv4a="$r_sv4a requirement-missing"
grep -qF '<tr><td>176</td>' requirements.html || r_sv4a="$r_sv4a appendix-disposition-missing"
grep -qF 'R-SV4a — direct-only viewer transport and state finality' HARDENING_STATUS.md \
  || r_sv4a="$r_sv4a ledger-disposition-missing"
if [ -n "$r_sv4a" ]; then
  echo "  FAIL R-SV4a direct-only viewer state/API finality:$r_sv4a"; rc=1
else
  echo "  ok  R-SV4a keyed direct stream + fixed label, no relay-choice state/ABI, direct pre-login policy"
fi
# R-SV5a: a rendezvous numeric ID is not a direct-address capability. Its obsolete CLI query must
# neither survive in argv dispatch nor redirect an installed-root Unix process into user main IPC.
r_sv5a=""
r_sv5a_core_main=$(awk '/^pub fn core_main\(\)/{capture=1} capture{print} /^fn core_main_invoke_new_connection\(/{exit}' src/core_main.rs)
r_sv5a_scope=$(awk '/^fn is_user_main_ipc_scope_cli_command\(/{capture=1} capture{print} capture && /^}/{exit}' src/core_main.rs)
echo "$r_sv5a_core_main" | grep -qF 'args[0] == "--get-id"' \
  && r_sv5a="$r_sv5a get-id-handler-present"
echo "$r_sv5a_core_main" | grep -qF 'println!("{}", crate::ipc::get_id());' \
  && r_sv5a="$r_sv5a get-id-print-present"
echo "$r_sv5a_scope" | grep -qF 'Some("--get-id")' \
  && r_sv5a="$r_sv5a get-id-user-main-ipc-scope-present"
echo "$r_sv5a_scope" | grep -qF 'Some("--option")' \
  || r_sv5a="$r_sv5a retained-management-scope-not-exact"
echo "$r_sv5a_scope" | grep -qF 'Some("--assign")' \
  && r_sv5a="$r_sv5a account-assignment-user-main-ipc-scope-present"
grep -qF 'fn obsolete_get_id_command_has_no_user_main_ipc_scope()' src/core_main.rs \
  || r_sv5a="$r_sv5a get-id-scope-regression-missing"
grep -qF '<span class="id">R-SV5a</span>' requirements.html \
  || r_sv5a="$r_sv5a requirement-missing"
grep -qF '<tr><td>177</td>' requirements.html \
  || r_sv5a="$r_sv5a appendix-disposition-missing"
grep -qF 'R-SV5a — obsolete numeric-ID query command and user-main-IPC scope' HARDENING_STATUS.md \
  || r_sv5a="$r_sv5a ledger-disposition-missing"
if [ -n "$r_sv5a" ]; then
  echo "  FAIL R-SV5a obsolete numeric-ID CLI and IPC-scope closure:$r_sv5a"; rc=1
else
  echo "  ok  R-SV5a --get-id handler absent and excluded from installed-root Unix user-main IPC scope"
fi
# R-G2/R-SV5: the viewer's only route identity is the exact direct address. The old formatter and
# controller vocabulary space-grouped numeric IDs, while its trim helper deleted every space before
# validation. Reject that API and require raw address display plus outer-whitespace-only normalization.
r_g2_address=""
[ ! -e flutter/lib/common/formatter/id_formatter.dart ] \
  || r_g2_address="$r_g2_address legacy-id-formatter-file-present"
if grep -RInE --include='*.dart' 'IDTextEditingController|IDTextInputFormatter|formatID|trimID' \
  flutter/lib >/dev/null; then
  r_g2_address="$r_g2_address legacy-numeric-id-api-present"
fi
grep -qF 'class DirectAddressTextEditingController extends TextEditingController' \
  flutter/lib/common/formatter/direct_address.dart \
  || r_g2_address="$r_g2_address direct-address-controller-missing"
grep -qF 'String normalizeDirectAddress(String address) => address.trim();' \
  flutter/lib/common/formatter/direct_address.dart \
  || r_g2_address="$r_g2_address outer-whitespace-only-normalizer-missing"
if grep -nF "replaceAll(' ', '')" flutter/lib/common.dart \
  flutter/lib/common/formatter/direct_address.dart flutter/lib/desktop/pages/connection_page.dart \
  flutter/lib/mobile/pages/connection_page.dart >/dev/null \
  || grep -nF 'replaceAll(" ", "")' flutter/lib/common.dart \
  flutter/lib/common/formatter/direct_address.dart flutter/lib/desktop/pages/connection_page.dart \
  flutter/lib/mobile/pages/connection_page.dart >/dev/null; then
  r_g2_address="$r_g2_address all-space-deletion-present"
fi
grep -qF 'connect(BuildContext context, String address,' flutter/lib/common.dart \
  || r_g2_address="$r_g2_address address-choke-point-signature-missing"
grep -qF 'address = normalizeDirectAddress(address);' flutter/lib/common.dart \
  || r_g2_address="$r_g2_address pre-validation-normalization-missing"
grep -qF '? widget.peer.id' flutter/lib/common/widgets/autocomplete.dart \
  || r_g2_address="$r_g2_address raw-autocomplete-address-display-missing"
[ "$(grep -Fc 'peer.alias.isEmpty ? peer.id : peer.alias' flutter/lib/common/widgets/peer_card.dart)" -eq 3 ] \
  || r_g2_address="$r_g2_address raw-peer-address-display-inventory-wrong"
grep -qF "const malformedIpv4 = '192. 168.1.10';" flutter/test/address_validator_test.dart \
  || r_g2_address="$r_g2_address interior-whitespace-regression-missing"
grep -qF 'Numeric-ID address formatter/controller — CLOSED/GATED (R-G2/R-SV5)' HARDENING_STATUS.md \
  || r_g2_address="$r_g2_address hardening-ledger-not-closed"
if [ -n "$r_g2_address" ]; then
  echo "  FAIL R-G2/R-SV5 direct-address UI model and exact-target preservation:$r_g2_address"; rc=1
else
  echo "  ok  R-G2/R-SV5 exact direct-address controller/choke point + raw peer rendering; numeric-ID formatter absent"
fi
# R-G6 ADDITIVE copy — the half the deletion-only greps never asserted (so it silently slipped): the
# direct-only failure/status semantics MUST be REWRITTEN, not merely have the relay copy deleted. Two
# MUST clauses: (a) a peer that DISABLED a capability surfaces a SPECIFIC "disabled on the peer"
# message, not a confusing generic connect failure; (b) an unreachable host gets actionable "check the
# address / port-forward" guidance (there is no relay fallback to suggest). Assert both lang keys exist
# in en.rs AND are wired in client.rs (present + referenced, not orphaned) so the copy cannot regress.
r_g6_add=""
grep -qF '"Capability disabled on the remote peer"' src/lang/en.rs || r_g6_add="$r_g6_add en:cap-disabled-key"
grep -qF '"direct_unreachable_tip"' src/lang/en.rs                  || r_g6_add="$r_g6_add en:unreachable-tip-key"
grep -qF '"Capability disabled on the remote peer"' src/client.rs   || r_g6_add="$r_g6_add wire:cap-disabled-msgbox"
grep -qF 'err.starts_with("No permission of")' src/client.rs        || r_g6_add="$r_g6_add wire:cap-refusal-detect"
grep -qF '"direct_unreachable_tip"' src/client.rs                   || r_g6_add="$r_g6_add wire:unreachable-msgbox"
grep -qF 'err.contains("Failed to connect")' src/client.rs          || r_g6_add="$r_g6_add wire:unreachable-detect"
if [ -n "$r_g6_add" ]; then
  echo "  FAIL R-G6: the direct-only ADDITIVE error/status copy is missing/unwired:$r_g6_add"; rc=1
else
  echo "  ok  R-G6 additive copy present+wired (capability-disabled-on-peer message + unreachable check-address/port-forward guidance)"
fi
# (2) The Rust core has no cross-server grammar or storage surface at all. The exact address remains
# opaque through LoginConfigHandler and any non-direct address is rejected at Client::_start.
r_x6_rust_address=""
grep -qF 'self.id = id;' src/client.rs || r_x6_rust_address="$r_x6_rust_address exact-address-assignment-missing"
grep -qF 'fn login_identity_does_not_parse_cross_server_grammar()' src/client.rs \
  || r_x6_rust_address="$r_x6_rust_address address-identity-regression-missing"
if grep -qE 'other_server|other-server-key|args_map\.remove\("key"\)|id\.contains\("@"\)' src/client.rs; then
  r_x6_rust_address="$r_x6_rust_address cross-server-parser-or-state-present"
fi
if [ -n "$r_x6_rust_address" ]; then
  echo "  FAIL R-X6: Rust client address identity is not structurally free of cross-server key grammar:$r_x6_rust_address"; rc=1
else
  echo "  ok  R-X6 Rust core retains the exact address and has no cross-server key parser or state"
fi
# R-X6 confirmation gate: a deep-link-initiated connection MUST be confirmed by the user. The Dart gate
# (confirmDeepLinkConnect via msgBox) wraps every rustdesk:// connect, routed through the `fromUri`
# discriminator so the user-typed CLI is NOT gated but every URI-derived connect is.
if grep -qF 'confirmDeepLinkConnect' flutter/lib/common.dart && grep -qF 'fromUri' flutter/lib/common.dart; then
  echo "  ok  R-X6 deep-link connect is confirmation-gated (confirmDeepLinkConnect + fromUri)"
else
  echo "  FAIL R-X6: the deep-link-connect confirmation gate (confirmDeepLinkConnect/fromUri) is missing"; rc=1
fi
# R-X6 deep-link WRITE authorities: rustdesk://config/<b64> (server + key trust-anchor write) and
# rustdesk://password/<pw> (permanent-password write) MUST be ignored, not honored (the same trust-anchor
# / credential-injection class as R-X4). Assert urlLinkToCmdArgs still treats them as ignore-return-null.
if grep -qF '["config", "password"].contains(uri.authority)' flutter/lib/common.dart && grep -qF 'Ignoring rustdesk:// server/credential write authority' flutter/lib/common.dart; then
  echo "  ok  R-X6 deep-link config/password WRITE authorities are ignored (no trust-anchor/credential write)"
else
  echo "  FAIL R-X6: the rustdesk://config + rustdesk://password WRITE authorities are not provably excised"; rc=1
fi
# R-X6/R-S14 Android manifest hardening — lock both source intent and final-APK artifact proof against
# regrowth. Library manifests are allowed to contain legacy declarations only when the app manifest removes
# them with merge markers; the signed APK is checked by build-android.sh through verify-android-apk-manifest.py.
AMF=flutter/android/app/src/main/AndroidManifest.xml
android_manifest_hardening=""
grep -qF 'xmlns:tools="http://schemas.android.com/tools"' "$AMF" || android_manifest_hardening="$android_manifest_hardening tools-namespace"
grep -qF 'android:allowBackup="false"' "$AMF" || android_manifest_hardening="$android_manifest_hardening allowBackup"
grep -qF '<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" tools:node="remove" />' "$AMF" || android_manifest_hardening="$android_manifest_hardening read-storage-remove"
grep -qF '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" tools:node="remove" />' "$AMF" || android_manifest_hardening="$android_manifest_hardening write-storage-remove"
grep -qF '<uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW" tools:node="remove" />' "$AMF" || android_manifest_hardening="$android_manifest_hardening overlay-remove"
if grep -E '<uses-permission[^>]+android:name="android.permission.(READ_EXTERNAL_STORAGE|WRITE_EXTERNAL_STORAGE|SYSTEM_ALERT_WINDOW)"' "$AMF" | grep -v 'tools:node="remove"' | grep -q .; then
  android_manifest_hardening="$android_manifest_hardening live-forbidden-permission"
fi
grep -qE '<service[^>]*FloatingWindowService' "$AMF" && android_manifest_hardening="$android_manifest_hardening floating-service"
grep -qE 'android:requestLegacyExternalStorage' "$AMF" && android_manifest_hardening="$android_manifest_hardening legacy-storage"
grep -A5 'android:name=".PermissionRequestTransparentActivity"' "$AMF" | grep -qF 'android:exported="false"' || android_manifest_hardening="$android_manifest_hardening permission-activity-export"
grep -A5 'android:name=".MainService"' "$AMF" | grep -qF 'android:exported="false"' || android_manifest_hardening="$android_manifest_hardening main-service-export"
grep -A3 'android:name="androidx.profileinstaller.ProfileInstallReceiver"' "$AMF" | grep -qF 'tools:node="remove"' || android_manifest_hardening="$android_manifest_hardening profileinstall-remove"
grep -qF 'cleartextTrafficPermitted="false"' flutter/android/app/src/main/res/xml/network_security_config.xml || android_manifest_hardening="$android_manifest_hardening cleartext-deny"
python3 -c 'import ast, pathlib; ast.parse(pathlib.Path("scripts/verify-android-apk-manifest.py").read_text(encoding="utf-8"))' || android_manifest_hardening="$android_manifest_hardening apk-manifest-helper-syntax"
grep -qF 'verify-android-apk-manifest.py' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening build-android-helper-call"
grep -qF -- '--aapt2 /online/android-sdk/build-tools/' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening build-android-aapt2"
grep -qF 'ANDROID_MIN_SDK="24"' scripts/pins.env || android_manifest_hardening="$android_manifest_hardening min-sdk-pin"
grep -qE 'minSdkVersion[[:space:]]+24\b' flutter/android/app/build.gradle || android_manifest_hardening="$android_manifest_hardening min-sdk-gradle"
grep -qF 'MIN_SDK_VERSION = 24' scripts/verify-android-apk-manifest.py || android_manifest_hardening="$android_manifest_hardening min-sdk-helper"
grep -qF -- '--env ANDROID_MIN_SDK="$ANDROID_MIN_SDK"' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening min-sdk-container-env"
grep -qF -- '--min-sdk-version "$ANDROID_MIN_SDK"' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening min-sdk-sign"
grep -qF -- '--v1-signing-enabled false' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening v1-disabled"
grep -qF -- '--v2-signing-enabled true' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening v2-enabled"
grep -qF -- '--v3-signing-enabled true' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening v3-enabled"
grep -qF 'apksigner verify -Werr --min-sdk-version' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening apksigner-werr"
grep -qF 'Verified using v1 scheme (JAR signing): false' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening v1-output-gate"
grep -qF 'not protected by signature' scripts/build-android.sh || android_manifest_hardening="$android_manifest_hardening unsigned-metainf-warning-gate"
grep -qF 'FORBIDDEN_COMPONENTS = {' scripts/verify-android-apk-manifest.py || android_manifest_hardening="$android_manifest_hardening forbidden-component-policy"
grep -qF 'androidx.profileinstaller.ProfileInstallReceiver' scripts/verify-android-apk-manifest.py || android_manifest_hardening="$android_manifest_hardening profileinstall-policy"
grep -qF 'FORBIDDEN_USES_PERMISSIONS = {' scripts/verify-android-apk-manifest.py || android_manifest_hardening="$android_manifest_hardening forbidden-permission-policy"
grep -qF 'ALLOWED_COMPONENTS =' scripts/verify-android-apk-manifest.py || android_manifest_hardening="$android_manifest_hardening component-inventory-policy"
if [ -z "$android_manifest_hardening" ]; then
  echo "  ok  R-X6/R-S14 Android manifest/signature authority hardened (source removes forbidden merges; internal components explicit; signed APK verifier wired; v1/JAR signing retired)"
else
  echo "  FAIL R-X6/R-S14: Android manifest hardening regressed:$android_manifest_hardening"; rc=1
fi
# R-X6 Android: the dead floating-window / SYSTEM_ALERT_WINDOW Dart UI is excised (commit 917ebd0; the
# native FloatingWindowService was cut in f8ddac8). Assert no LIVE kSystemAlertWindow reference regrows in
# the Flutter UI — a regrown overlay-permission request would re-introduce the dropped permission AND the
# canStartOnBoot silent-disable boot-start bug. (Filter the grep -rn 'file:line:' prefix so the lone
# explanatory comment in consts.dart is not a false positive.)
if grep -rn 'kSystemAlertWindow' flutter/lib/ | grep -vE ':[0-9]+:[[:space:]]*//' | grep -q .; then
  echo "  FAIL R-X6: a live kSystemAlertWindow reference regrew in flutter/lib (floating-window/overlay UI)"; rc=1
else
  echo "  ok  R-X6 Android floating-window / SYSTEM_ALERT_WINDOW Dart UI excised (no live ref)"
fi
# R-G1/R-G2 (§19): the mobile QR scanner is EXCISED, not just neutered. Its config-QR import backend
# was dead (R-X4/R-X6) and the fork generates no QR to scan (the ID-sharing QR generator is gone,
# R-G2); the lone surviving path (rustdesk://<addr> -> direct connect) is redundant with the connect
# box, so the whole scanner (camera + gallery-image + deep-link parser = untrusted-input surface) is
# removed. Assert the page, the live refs, and the scanner-only deps are all absent. (The flutter/lib
# grep filters `//` comment lines so the settings_page excision-rationale comment is not a false hit.)
if [ -e flutter/lib/mobile/pages/scan_page.dart ]; then
  echo "  FAIL R-G1/R-G2: scan_page.dart regrew (QR scanner page)"; rc=1
elif grep -rn 'ScanButton\|ScanPage\|QRView\|qr_code_scanner' flutter/lib/ | grep -vE ':[0-9]+:[[:space:]]*//' | grep -q .; then
  echo "  FAIL R-G1/R-G2: a live QR-scanner reference regrew in flutter/lib (ScanButton/ScanPage/QRView/qr_code_scanner)"; rc=1
elif grep -qE '^[[:space:]]*(qr_code_scanner|zxing2|image_picker):' flutter/pubspec.yaml; then
  echo "  FAIL R-G1/R-G2: a QR/image-scanner dep regrew in pubspec.yaml (qr_code_scanner/zxing2/image_picker)"; rc=1
else
  echo "  ok  R-G1/R-G2 mobile QR scanner fully excised (page + live refs + qr_code_scanner/zxing2/image_picker deps gone)"
fi
# R-X8/R-X6 terminal-admin (run-as-administrator) viewer mode -- EXCISED. It set IS_TERMINAL_ADMIN=Y, which
# client.rs handle_hash short-circuited into a msgbox ("terminal-admin-login") the Flutter model has NO
# handler for -> a guaranteed blank-dialog dead-end that then closes the connection (a 100%-failure
# affordance). The field + env + the get_key admin branch + the 5 peer-card menu items + the --terminal-admin
# CLI + the terminal-admin deep-link are all removed; the plain (non-admin) _terminalAction stays. (The inert
# terminal-admin-login-tip lang strings are harmless localization data and are intentionally left in place.)
ra6_clean 'is_terminal_admin|IS_TERMINAL_ADMIN|terminal-admin-service-id' 'R-X8/R-X6 terminal-admin viewer field/env/service-id-key' || rc=1
if grep -rqE 'setEnvTerminalAdmin|_terminalRunAsAdminAction|IS_TERMINAL_ADMIN|terminal-admin|isTerminalRunAsAdmin' flutter/lib/; then
  echo "  FAIL R-X8/R-X6: a terminal-admin (run-as-administrator) trigger regrew in flutter/lib"; rc=1
elif grep -rqF '_terminalAction(context)' flutter/lib/common/widgets/peer_card.dart; then
  echo "  ok  R-X8/R-X6 terminal-admin viewer mode excised (env/method/menu/CLI/deep-link); non-admin terminal kept"
else
  echo "  FAIL R-X8/R-X6: the non-admin _terminalAction was lost (over-excision)"; rc=1
fi
ra6_clean 'ConfigureUpdate|TestNatResponse'                              'R-X3 server-push config-update + NAT-response rewrite arms' || rc=1
# R-P3 / R-P14: the inherited insecure direct-mode used a plaintext constant-byte ack ("direct-ok")
# to admit a peer WITHOUT the PAKE key-confirmation. The fork makes CPace mandatory (R-A1), so any
# such constant ack MUST stay absent — its return would be a PAKE bypass.
ra6_clean 'direct-ok'                                                     'R-P3 insecure constant-byte ack (direct-ok), PAKE bypass' || rc=1
ra6_clean 'RUSTDESK_FORCED_DISPLAY_SERVER'                                'R-X12 display-server knob' || rc=1
# R-X12: is_x11() is compile-pinned `true` in BOTH the main crate (src/platform/linux.rs) and scrap
# (libs/scrap/src/common/mod.rs) — the capture+input backend is X11 with NO runtime display-server
# selector (the `*IS_X11` detection cache + the is_x11_or_headless() body are gone). Startup-asserted
# (R-A4, direct_service). Guards a regression that re-adds runtime capture/input backend selection.
r_x12_pin=
grep -A1 'pub fn is_x11() -> bool {' src/platform/linux.rs        | grep -qE '^\s*true\s*$' || r_x12_pin="$r_x12_pin main-is_x11"
grep -A1 'pub fn is_x11() -> bool {' libs/scrap/src/common/mod.rs | grep -qE '^\s*true\s*$' || r_x12_pin="$r_x12_pin scrap-is_x11"
grep -q 'static ref IS_X11' src/platform/linux.rs && r_x12_pin="$r_x12_pin IS_X11-cache-returned"
if [ -n "$r_x12_pin" ]; then
  echo "  FAIL R-X12: is_x11() X11-pin incomplete:$r_x12_pin"; rc=1
else
  echo "  ok  R-X12 is_x11() compile-pinned true (main + scrap; no runtime display-server selection)"
fi
# R-X12: get_display_server() is ALSO compile-pinned to the X11 constant — NOT just is_x11(). The
# session-admission gate (server::connection "Unsupported display server type") and ui_interface
# get_error() consult get_display_server(), not is_x11(); leaving it a runtime probe (loginctl /
# stray session-type) let a seatless/container session still REFUSE an incoming connection — the
# exact failure R-X12 says the x11 pin eliminates ("determinism a property of the binary, so no
# operator ever needs the env override"). The body MUST be the constant return, no runtime probe.
# (Comment lines are stripped before the probe check so the rationale can name the removed probe.)
r_x12_gds_code="$(awk '/^pub fn get_display_server\(\) -> String \{/{f=1} f && $0 !~ /^[[:space:]]*\/\//{print} f && /^\}/{exit}' libs/hbb_common/src/platform/linux.rs)"
if printf '%s\n' "$r_x12_gds_code" | grep -qE 'DISPLAY_SERVER_X11' \
   && ! printf '%s\n' "$r_x12_gds_code" | grep -qE 'run_loginctl|XDG_SESSION_TYPE'; then
  echo "  ok  R-X12 get_display_server() compile-pinned to the X11 constant (no runtime probe; refuse-path cannot misfire)"
else
  echo "  FAIL R-X12: get_display_server() still runtime-probes — the 'Unsupported display server type' refuse-path can misfire (R-X12 promise undelivered)"; rc=1
fi
# R-X12 (§8) — the Wayland/pipewire CAPTURE path is COMPILED OUT (the CI-grep deliverable): the scrap
# `wayland` feature + `mod wayland` (libs/scrap/src/wayland/ — the xdg-portal ScreenCast + restore-token
# persistence, R-S14) are REMOVED; X11 is the sole compile-pinned capture backend (the gstreamer/dbus/
# zbus pipewire surface is no longer linked). Asserts the feature enabling, `mod wayland`, directory,
# and both formerly orphaned source files are absent; uncompiled compatibility source is not accepted.
r_x12_cap=
grep -qE 'scrap = .*wayland'                Cargo.toml            && r_x12_cap="$r_x12_cap root-scrap-wayland-feature"
grep -qE '^wayland = \['                     libs/scrap/Cargo.toml && r_x12_cap="$r_x12_cap scrap-wayland-feature"
grep -rqE '^[[:space:]]*(pub )?mod wayland'   libs/scrap/src        && r_x12_cap="$r_x12_cap scrap-mod-wayland"
if [ -e libs/scrap/src/wayland ] || [ -L libs/scrap/src/wayland ]; then
  r_x12_cap="$r_x12_cap scrap-wayland-dir"
fi
if [ -e libs/scrap/src/wayland.rs ] || [ -L libs/scrap/src/wayland.rs ]; then
